function actionClickCost(action: LegalAction): number {
  return Math.max(
    1,
    action.costs.reduce(
      (sum, cost) =>
        sum + (Number.isFinite(cost.clicks) ? (cost.clicks ?? 0) : 0),
      0,
    ),
  );
}

