    corpAssetEconomyRemoteRoleSeen: 0,
    corpBaitRemoteRoleSeen: 0,
    corpAmbushRemoteRoleSeen: 0,
    corpIceModifierRemoteRoleSeen: 0,
    corpRemoteRoleRaisedSafetyScore: 0,
