function corpFutureRunIceDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "corp" || action.side !== "corp") return {};
  const opportunity = input.legalActions.some(
    (candidate) =>
      candidate.side === "corp" &&
      candidate.type === "install_card" &&
      candidate.payload?.placement === "ice" &&
      Boolean(
        classifyCorpFutureRunIceDefinitionId(
          sourceDefinitionIdForSimulationAction(input, candidate),
        ),
      ),
  );
  const assessment = assessCorpFutureRunIcePlacement(input, action);
  if (!assessment) {
    return opportunity ? { corpFutureRunIceInstallOpportunity: true } : {};
  }
  return {
    ...(opportunity ? { corpFutureRunIceInstallOpportunity: true } : {}),
    corpFutureRunIceInstalled: true,
    corpFutureRunIceClass: assessment.futureRunIceClass,
    ...(assessment.installedOnEmptyServer
      ? {
          corpFutureRunIceInstalledOnEmptyServer: true,
          corpFutureRunIceInstalledFirstOnEmptyServer: true,
          corpFutureRunIceInstalledAsInnermost: true,
          corpFutureRunIceInstalledWithoutLaterIce: true,
          corpFutureRunIceInstalledAsDeadEffect: true,
          corpIceOrderFutureEffectDead: true,
        }
      : {
          corpFutureRunIceInstalledAfterInnerIceExists: true,
          corpFutureRunIceInstalledWithLaterIce: true,
          corpFutureRunIceInstalledAsLiveEffect: true,
          corpIceOrderFutureEffectLive: true,
        }),
    corpFutureRunIceInstalledAsOutermost: true,
    ...(assessment.deadEffect &&
    (assessment.futureRunIceClass === "bolter_or_data_darts" ||
      assessment.futureRunIceClass === "future_run_ice")
      ? { corpNextIceEffectInstalledLast: true }
      : {}),
    ...(assessment.futureRunIceClass === "ball_and_chain" &&
    assessment.deadEffect
      ? {
          corpBallAndChainInstalledInnermost: true,
          corpBallAndChainInstalledWithoutLaterIce: true,
        }
      : {}),
    ...(assessment.futureRunIceClass === "ball_and_chain" &&
    assessment.liveEffect
      ? { corpBallAndChainInstalledWithLaterIce: true }
      : {}),
    ...(assessment.futureRunIceClass === "canis" && assessment.deadEffect
      ? { corpCanisInstalledWithoutLaterIce: true }
      : {}),
    ...(assessment.futureRunIceClass === "bolter_or_data_darts" &&
    assessment.deadEffect
      ? { corpBolterOrDataDartsInstalledWithoutNextIce: true }
      : {}),
  };
}

function corpScoreTerminalDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "corp" || action.side !== "corp") return {};
  const terminal = assessCorpScoreTerminalWindow(input);
  if (!terminal.terminalWindow) return {};
  const scoreTaken = terminal.scoreActionIds.includes(action.actionId);
  const advanceTaken = terminal.advanceToScoreActionIds.includes(
    action.actionId,
  );
  const agendaInstalled = terminal.agendaInstallActionIds.includes(
    action.actionId,
  );
  const taken = scoreTaken || advanceTaken || agendaInstalled;
  const skipped = !taken;
  const family = corpScoreTerminalChosenFamily(input, action);
  const fixGateBlocked =
    terminal.blockedByCheapContest ||
    terminal.blockedByCredits ||
    terminal.blockedByRunnerContest ||
    terminal.blockedByHqThreat;
  const suspiciousProtection =
    skipped && !fixGateBlocked && family === "protection";
  const suspiciousEconomy = skipped && !fixGateBlocked && family === "economy";
  const suspiciousDraw = skipped && !fixGateBlocked && family === "draw";
  const suspiciousRemotePortfolio =
    skipped && !fixGateBlocked && family === "remote_portfolio";
  const suspiciousUnknown =
    skipped &&
    !fixGateBlocked &&
    !suspiciousProtection &&
    !suspiciousEconomy &&
    !suspiciousDraw &&
    !suspiciousRemotePortfolio;
  return {
    corpScoreTerminalWindow: true,
    ...(terminal.scoreActionIds.length > 0
      ? { corpScoreTerminalWindowScoreLegal: true }
      : {}),
    ...(terminal.advanceToScoreActionIds.length > 0
      ? { corpScoreTerminalWindowAdvanceToScoreLegal: true }
      : {}),
    ...(terminal.agendaInstallActionIds.length > 0
      ? { corpScoreTerminalWindowAgendaInstallLegal: true }
      : {}),
    ...(terminal.protectedRemoteIds.length > 0
      ? { corpScoreTerminalWindowProtectedRemoteReady: true }
      : {}),
    ...(terminal.remoteContestLow
      ? { corpScoreTerminalWindowRemoteContestLow: true }
      : {}),
    ...(terminal.creditsSufficient
      ? { corpScoreTerminalWindowCreditsSufficient: true }
      : {}),
    ...(terminal.runnerAccessThreatHigh
      ? { corpScoreTerminalWindowRunnerAccessThreatHigh: true }
      : {}),
    ...(scoreTaken ? { corpScoreTerminalScoreTaken: true } : {}),
    ...(advanceTaken ? { corpScoreTerminalAdvanceTaken: true } : {}),
    ...(agendaInstalled ? { corpScoreTerminalAgendaInstalled: true } : {}),
    ...(skipped ? { corpScoreTerminalSkipped: true } : {}),
    ...(skipped && family === "protection"
      ? { corpScoreTerminalSkippedForProtection: true }
      : {}),
    ...(skipped && family === "economy"
      ? { corpScoreTerminalSkippedForEconomy: true }
      : {}),
    ...(skipped && family === "draw"
      ? { corpScoreTerminalSkippedForDraw: true }
      : {}),
    ...(skipped && family === "install_ice"
      ? { corpScoreTerminalSkippedForInstallIce: true }
      : {}),
    ...(skipped && family === "install_asset_or_upgrade"
      ? { corpScoreTerminalSkippedForInstallAssetOrUpgrade: true }
      : {}),
    ...(skipped && family === "hq_protection"
      ? { corpScoreTerminalSkippedForHqProtection: true }
      : {}),
    ...(skipped && family === "rnd_protection"
      ? { corpScoreTerminalSkippedForRndProtection: true }
      : {}),
    ...(skipped && family === "remote_portfolio"
      ? { corpScoreTerminalSkippedForRemotePortfolio: true }
      : {}),
    ...(skipped && family === "unknown"
      ? { corpScoreTerminalSkippedForUnknownHigherPriority: true }
      : {}),
    ...(terminal.blockedByCheapContest
      ? { corpScoreConversionFixGateBlockedByCheapContest: true }
      : {}),
    ...(terminal.blockedByCredits
      ? { corpScoreConversionFixGateBlockedByCredits: true }
      : {}),
    ...(terminal.blockedByRunnerContest
      ? { corpScoreConversionFixGateBlockedByRunnerContest: true }
      : {}),
    ...(terminal.blockedByHqThreat
      ? { corpScoreConversionFixGateBlockedByHqThreat: true }
      : {}),
    ...(suspiciousProtection
      ? {
          corpScoreConversionFixGateEligible: true,
          corpScoreConversionFixGateSuspiciousProtectionLoop: true,
        }
      : {}),
    ...(suspiciousEconomy
      ? {
          corpScoreConversionFixGateEligible: true,
          corpScoreConversionFixGateSuspiciousEconomyLoop: true,
        }
      : {}),
    ...(suspiciousDraw
      ? {
          corpScoreConversionFixGateEligible: true,
          corpScoreConversionFixGateSuspiciousDraw: true,
        }
      : {}),
    ...(suspiciousRemotePortfolio
      ? {
          corpScoreConversionFixGateEligible: true,
          corpScoreConversionFixGateSuspiciousRemotePortfolio: true,
        }
      : {}),
    ...(suspiciousUnknown
      ? {
          corpScoreConversionFixGateEligible: true,
          corpScoreConversionFixGateSuspiciousUnknown: true,
        }
      : {}),
    corpScoreTerminalEvidence: terminal.evidence,
  };
}

function corpEconomyBeforeScoreDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "corp" || action.side !== "corp") return {};
  const terminal = assessCorpScoreTerminalWindow(input);
  if (!terminal.terminalWindow) return {};
  const family = corpScoreTerminalChosenFamily(input, action);
  const economyTaken = family === "economy";
  const hasInstalledAgenda =
    terminal.scoreActionIds.length > 0 ||
    terminal.advanceToScoreActionIds.length > 0;
  const hasAdvancedAgenda = hasInstalledAgenda;
  const scoreLegal = terminal.scoreActionIds.length > 0;
  const advanceToScoreLegal = terminal.advanceToScoreActionIds.length > 0;
  const agendaInstallReadyRemoteLegal =
    terminal.agendaInstallActionIds.length > 0 &&
    terminal.protectedRemoteIds.length > 0;
  const fixGateBlockedBySafety = terminal.blockedByHqThreat;
  const fixGateBlocked =
    terminal.blockedByCredits ||
    terminal.blockedByCheapContest ||
    terminal.blockedByRunnerContest ||
    fixGateBlockedBySafety;
  const creditsNeeded = economyTaken && terminal.blockedByCredits;
  const creditsAlreadyEnough = !terminal.blockedByCredits;
  const suspiciousCreditsAlreadyEnough =
    economyTaken && creditsAlreadyEnough && !fixGateBlocked;
  const suspiciousDelayedTerminalAction =
    economyTaken &&
    !fixGateBlocked &&
    (scoreLegal || advanceToScoreLegal || agendaInstallReadyRemoteLegal);
  const suspiciousRemoteStillSafe =
    economyTaken && !fixGateBlocked && terminal.protectedRemoteIds.length > 0;
  const unclassified =
    economyTaken &&
    !creditsNeeded &&
    !suspiciousCreditsAlreadyEnough &&
    !suspiciousDelayedTerminalAction &&
    !suspiciousRemoteStillSafe &&
    !fixGateBlocked;
  const evidence = [
    "corp_economy_before_score_diagnostic_window:true",
    `corp_economy_before_score_score_legal:${scoreLegal}`,
    `corp_economy_before_score_advance_to_score_legal:${advanceToScoreLegal}`,
    `corp_economy_before_score_agenda_install_ready_remote_legal:${agendaInstallReadyRemoteLegal}`,
    `corp_economy_before_score_credits_short:${terminal.blockedByCredits}`,
    `corp_economy_before_score_credits_already_enough:${creditsAlreadyEnough}`,
    `corp_economy_before_score_remote_safe:${terminal.protectedRemoteIds.length > 0}`,
    `corp_economy_before_score_runner_contest_high:${terminal.blockedByRunnerContest}`,
  ];

  return {
    corpEconomyBeforeScoreDiagnosticWindow: true,
    ...(hasInstalledAgenda
      ? { corpEconomyBeforeScoreWindowWithInstalledAgenda: true }
      : {}),
    ...(hasAdvancedAgenda
      ? { corpEconomyBeforeScoreWindowWithAdvancedAgenda: true }
      : {}),
    ...(scoreLegal
      ? { corpEconomyBeforeScoreWindowWithScoreLegalNext: true }
      : {}),
    ...(advanceToScoreLegal
      ? { corpEconomyBeforeScoreWindowWithAdvanceToScoreLegalNext: true }
      : {}),
    ...(terminal.protectedRemoteIds.length > 0
      ? {
          corpEconomyBeforeScoreWindowWithReadyRemote: true,
          corpEconomyBeforeScoreWindowRemoteSafe: true,
        }
      : {}),
    ...(agendaInstallReadyRemoteLegal
      ? { corpEconomyBeforeScoreWindowWithAgendaInHqAndReadyRemote: true }
      : {}),
    ...(terminal.blockedByCredits
      ? { corpEconomyBeforeScoreWindowCreditsShort: true }
      : { corpEconomyBeforeScoreWindowCreditsAlreadyEnough: true }),
    ...(terminal.blockedByRunnerContest
      ? { corpEconomyBeforeScoreWindowRemoteContestHigh: true }
      : {}),
    ...(economyTaken ? { corpEconomyBeforeScoreTaken: true } : {}),
    ...(creditsNeeded
      ? {
          corpEconomyBeforeScoreTakenAsNecessaryCredits: true,
          corpEconomyBeforeScorePlausibleCreditsNeeded: true,
          corpEconomyBeforeScorePlausibleRezOrAdvanceReserve: true,
        }
      : {}),
    ...(economyTaken && creditsAlreadyEnough
      ? { corpEconomyBeforeScoreTakenDespiteCreditsEnough: true }
      : {}),
    ...(economyTaken && scoreLegal
      ? { corpEconomyBeforeScoreTakenOverScoreLegal: true }
      : {}),
    ...(economyTaken && advanceToScoreLegal
      ? { corpEconomyBeforeScoreTakenOverAdvanceToScoreLegal: true }
      : {}),
    ...(economyTaken && agendaInstallReadyRemoteLegal
      ? { corpEconomyBeforeScoreTakenOverAgendaInstallReadyRemote: true }
      : {}),
    ...(economyTaken && agendaInstallReadyRemoteLegal
      ? { corpEconomyBeforeScoreTakenOverHqAgendaExit: true }
      : {}),
    ...(terminal.blockedByHqThreat
      ? { corpEconomyBeforeScorePlausibleHqOrRndSafety: true }
      : {}),
    ...(terminal.blockedByRunnerContest
      ? { corpEconomyBeforeScorePlausibleRunnerContestTooHigh: true }
      : {}),
    ...(economyTaken &&
    !scoreLegal &&
    !advanceToScoreLegal &&
    !agendaInstallReadyRemoteLegal
      ? { corpEconomyBeforeScorePlausibleNoAgendaExit: true }
      : {}),
    ...(suspiciousCreditsAlreadyEnough
      ? { corpEconomyBeforeScoreSuspiciousCreditsAlreadyEnough: true }
      : {}),
    ...(suspiciousDelayedTerminalAction
      ? { corpEconomyBeforeScoreSuspiciousDelayedTerminalAction: true }
      : {}),
    ...(suspiciousRemoteStillSafe
      ? { corpEconomyBeforeScoreSuspiciousRemoteStillSafe: true }
      : {}),
    ...(unclassified ? { corpEconomyBeforeScoreUnclassified: true } : {}),
    ...(terminal.blockedByCredits
      ? { corpEconomyBeforeScoreFixGateBlockedByCredits: true }
      : {}),
    ...(terminal.blockedByCheapContest
      ? { corpEconomyBeforeScoreFixGateBlockedByCheapContest: true }
      : {}),
    ...(terminal.blockedByRunnerContest
      ? { corpEconomyBeforeScoreFixGateBlockedByRunnerContest: true }
      : {}),
    ...(fixGateBlockedBySafety
      ? { corpEconomyBeforeScoreFixGateBlockedBySafety: true }
      : {}),
    ...(economyTaken && !fixGateBlocked
      ? {
          corpEconomyBeforeScoreFixGateEligible: true,
          corpEconomyBeforeScoreFixGateSuspicious:
            suspiciousCreditsAlreadyEnough ||
            suspiciousDelayedTerminalAction ||
            suspiciousRemoteStillSafe,
        }
      : {}),
    corpEconomyBeforeScoreEvidence: evidence,
  };
}

function corpScoreTerminalChosenFamily(
  input: AiDecisionInput,
  action: LegalAction,
):
  | "protection"
  | "economy"
  | "draw"
  | "install_ice"
  | "install_asset_or_upgrade"
  | "hq_protection"
  | "rnd_protection"
  | "remote_portfolio"
  | "unknown" {
  if (action.type === "draw_card") return "draw";
  if (action.type === "gain_credit") return "economy";
  const roles = rolesForAction(input, action);
  if (roles.some((role) => role.includes("economy"))) return "economy";
  if (
    action.type === "install_card" &&
    action.payload?.placement === "ice" &&
    action.payload?.serverId === "hq"
  )
    return "hq_protection";
  if (
    action.type === "install_card" &&
    action.payload?.placement === "ice" &&
    action.payload?.serverId === "rd"
  )
    return "rnd_protection";
  if (action.type === "install_card" && action.payload?.placement === "ice") {
    if (action.payload?.serverId === "new_remote") return "remote_portfolio";
    return "install_ice";
  }
  if (action.type === "install_card" && action.payload?.placement !== "ice") {
    if (action.payload?.serverId === "new_remote") return "remote_portfolio";
    if (
      roles.some(
        (role) =>
          role === "remote_support" ||
          role === "remote_protection" ||
          role === "upgrade" ||
          role === "run_tax" ||
          role === "steal_tax",
      )
    )
      return "protection";
    return "install_asset_or_upgrade";
  }
  if (
    action.type === "play_operation" ||
    action.type === "trigger_ability" ||
    action.type === "activated_card_ability"
  )
    return roles.some((role) => role.includes("economy"))
      ? "economy"
      : "unknown";
  return "unknown";
}

function runnerBreakerCoverageDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "runner" || action.side !== "runner") return {};
  const pressure = assessRunnerCoveragePressureForMetrics(input);
  const pressureReady = assessRunnerPressureReadyForMetrics(input);
  const pressureReadyTargetTypes = new Set(
    pressureReady.readyTargets.map((target) => target.targetType),
  );
  const selectedPressureReadyTarget =
    action.type === "start_run" &&
    targetServerId !== undefined &&
    pressureReady.readyTargets.some(
      (target) => target.serverId === targetServerId,
    );
  const setupContinuation =
    action.type === "draw_card" ||
    action.type === "gain_credit" ||
    isRunnerEconomyAction(input, action) ||
    runnerCoverageSearchActionForMetrics(input, action) ||
    (action.type === "install_card" && isRunnerRigInstallAction(input, action));
  const pressureReadyFlags = {
    ...(pressureReady.broadReady ? { runnerPressureReadyWindow: true } : {}),
    ...(pressureReady.readyTargets.length > 0
      ? { runnerPressureReadyTrue: true }
      : {}),
    ...(pressureReady.falsePositive
      ? { runnerPressureReadyFalsePositive: true }
      : {}),
    ...(pressureReadyTargetTypes.has("hq")
      ? { runnerPressureReadyByTargetHq: true }
      : {}),
    ...(pressureReadyTargetTypes.has("rnd")
      ? { runnerPressureReadyByTargetRnd: true }
      : {}),
    ...(pressureReadyTargetTypes.has("archives")
      ? { runnerPressureReadyByTargetArchives: true }
      : {}),
    ...(pressureReadyTargetTypes.has("remote")
      ? { runnerPressureReadyByTargetRemote: true }
      : {}),
    ...(pressureReady.readyTargets.length > 0 && setupContinuation
      ? {
          runnerSetupContinuedAfterPressureReady: true,
          runnerSetupLoopAfterPressureReady: true,
        }
      : {}),
    ...(selectedPressureReadyTarget
      ? { runnerPressureTakenAfterCoverageReady: true }
      : {}),
    ...(pressureReady.readyTargets.length > 0 && !selectedPressureReadyTarget
      ? {
          runnerPressureSkippedAfterCoverageReady: true,
          runnerPressureSkippedReason: setupContinuation
            ? ("better_immediate_action" as const)
            : ("no_valuable_target" as const),
        }
      : {}),
    ...(pressureReady.blockers.has("insufficient_credits")
      ? { runnerPhaseExitBlockedByCost: true }
      : {}),
    ...(pressureReady.blockers.has("missing_post_run_reserve")
      ? { runnerPhaseExitBlockedByCost: true }
      : {}),
    ...(pressure.missingBreakerRoles.size > 0
      ? { runnerPhaseExitBlockedByCoverage: true }
      : {}),
    ...(pressureReady.falsePositive ||
    pressureReady.blockers.has("no_valuable_target")
      ? { runnerPhaseExitBlockedByTargetValue: true }
      : {}),
  };
  if (pressure.missingBreakerRoles.size === 0) {
    const pressureRun =
      action.type === "start_run" &&
      targetServerId !== undefined &&
      selectedPressureReadyTarget;
    return {
      ...pressureReadyFlags,
      ...(pressureReady.readyTargets.length > 0 && setupContinuation
        ? {
            runnerCoverageReadyButNoPressure: true,
            runnerSetupContinuedAfterCoverageReady: true,
          }
        : {}),
      ...(pressureRun ? { runnerPhaseExitToPressure: true } : {}),
    };
  }
  const searchAvailable = pressure.searchActionIds.size > 0;
  const searchUsed =
    pressure.searchActionIds.has(action.actionId) ||
    pressure.recoveryActionIds.has(action.actionId);
  const installable = pressure.matchingInstallActionIds.size > 0;
  const breakerInstall =
    action.type === "install_card" &&
    pressure.matchingInstallActionIds.has(action.actionId);
  const pathBlocked = pressure.blockedServers.size > 0;
  const runTaken =
    action.type === "start_run" &&
    targetServerId !== undefined &&
    pressure.blockedServers.has(targetServerId);
  const setupAction =
    action.type === "draw_card" ||
    action.type === "gain_credit" ||
    isRunnerEconomyAction(input, action) ||
    (action.type === "install_card" && isRunnerRigInstallAction(input, action));
  const pressureRun =
    action.type === "start_run" &&
    targetServerId !== undefined &&
    selectedPressureReadyTarget;

  return {
    ...pressureReadyFlags,
    runnerMissingBreakerCoverageByType: pressure.missingBreakerRoles.size,
    runnerVisibleIceBlockingByType: pressure.blockedServers.size,
    runnerKnownIceBlockingByType: pressure.knownIceBlockedServers.size,
    ...(pathBlocked ? { runnerPathBlockedByMissingCoverage: true } : {}),
    ...(installable ? { runnerInstallableBreakerForBlockedPath: true } : {}),
    ...(searchAvailable
      ? { runnerSearchCardAvailableForMissingBreaker: true }
      : {}),
    ...(searchUsed ? { runnerSearchCardUsedForMissingBreaker: true } : {}),
    ...(searchAvailable && !searchUsed
      ? { runnerSearchCardAvailableButUnused: true }
      : {}),
    ...(searchUsed && pressure.recoveryActionIds.has(action.actionId)
      ? { runnerTutorConvertedToBreakerInstall: true }
      : {}),
    ...(breakerInstall ? { runnerCoverageImproved: true } : {}),
    ...(breakerInstall ? { runnerTutorConvertedToBreakerInstall: true } : {}),
    ...(runTaken && pathBlocked
      ? { runnerProbeRevealedIceButDidNotReact: true }
      : {}),
    ...(searchUsed && pathBlocked
      ? { runnerProbeRevealedIceThenSearchedBreaker: true }
      : {}),
    ...(setupAction && pathBlocked
      ? { runnerSetupBreakerSearchStalled: true }
      : {}),
    ...(isRunnerEconomyAction(input, action) && pathBlocked
      ? { runnerSetupEconomyStalled: true }
      : {}),
    ...(pressureRun ? { runnerPhaseExitToPressure: true } : {}),
  };
}

function runnerHasReadyPressureRunForMetrics(input: AiDecisionInput): boolean {
  return input.legalActions.some((action) => {
    if (
      action.type !== "start_run" ||
      typeof action.payload?.serverId !== "string"
    )
      return false;
    const serverId = action.payload.serverId;
    const server = input.playerView.servers.find(
      (candidate) => candidate.id === serverId,
    );
    if (!server || !runnerStrategicBreakerTargetForMetrics(server))
      return false;
    const assessment = assessKnownRezzedIcePath(
      server.ice,
      input.playerView.own.rig ?? [],
      input.playerView.own.credits,
      server.root,
    );
    return !assessment.blocked;
  });
}

function assessRunnerPressureReadyForMetrics(
  input: AiDecisionInput,
): RunnerPressureReadyForMetrics {
  const readyTargets: RunnerPressureReadyTargetForMetrics[] = [];
  const blockers = new Set<
    | "insufficient_credits"
    | "missing_post_run_reserve"
    | "stale_central"
    | "remote_too_dangerous"
    | "no_valuable_target"
  >();
  let broadReady = false;
  const seen = new Set<string>();
  for (const action of input.legalActions) {
    if (
      action.type !== "start_run" ||
      typeof action.payload?.serverId !== "string"
    )
      continue;
    const serverId = action.payload.serverId;
    if (seen.has(serverId)) continue;
    seen.add(serverId);
    const server = input.playerView.servers.find(
      (candidate) => candidate.id === serverId,
    );
    if (!server || !runnerStrategicBreakerTargetForMetrics(server)) continue;
    const assessment = assessKnownRezzedIcePath(
      server.ice,
      input.playerView.own.rig ?? [],
      input.playerView.own.credits,
      server.root,
    );
    const visibleBreakCost = assessment.visibleBreakCost ?? 0;
    const creditsAfterPath = input.playerView.own.credits - visibleBreakCost;
    if (!assessment.blocked) broadReady = true;
    if (assessment.blocked) {
      blockers.add(
        visibleBreakCost > input.playerView.own.credits
          ? "insufficient_credits"
          : "no_valuable_target",
      );
      continue;
    }
    if (serverId.startsWith("remote_")) {
      const remoteReady = runnerRemotePressureReadyForMetrics(
        input,
        server,
        creditsAfterPath,
      );
      if (remoteReady) readyTargets.push({ serverId, targetType: "remote" });
      else blockers.add("no_valuable_target");
      continue;
    }
    const central = centralServerId(serverId);
    if (!central) continue;
    if (creditsAfterPath < 1) {
      blockers.add("missing_post_run_reserve");
      continue;
    }
    if (!centralPressureTargetIsGoodForMetrics(input, central)) {
      blockers.add("stale_central");
      continue;
    }
    readyTargets.push({
      serverId,
      targetType: central === "rd" ? "rnd" : central,
    });
  }
  return {
    broadReady,
    readyTargets,
    falsePositive: broadReady && readyTargets.length === 0,
    blockers,
  };
}

function runnerRemotePressureReadyForMetrics(
  input: AiDecisionInput,
  server: AiDecisionInput["playerView"]["servers"][number],
  creditsAfterPath: number,
): boolean {
  const hasVisibleScoreThreat = server.root.some(
    (card) =>
      (card.advancementCounters ?? 0) > 0 ||
      (card.known && card.type === "agenda"),
  );
  const knownMemory =
    reconstructBeliefState(input).runnerOpponentModel?.knownPositionMemory ??
    [];
  const knownRemoteEntries = knownMemory.filter(
    (entry) =>
      entry.zone === server.id && entry.positionKey.startsWith("root:"),
  );
  const knownAgenda = knownRemoteEntries.some(
    (entry) => definitionTypeForMetrics(entry.definitionId) === "agenda",
  );
  const relevantTrash = server.root.some((card) => {
    if (!card.known) return false;
    const trashCost = remoteRootTrashCostForMetrics(card);
    if (trashCost === undefined || creditsAfterPath < trashCost + 1)
      return false;
    if (!card.definitionId) return false;
    const type = definitionTypeForMetrics(card.definitionId);
    return type === "asset" || type === "upgrade";
  });
  return (
    creditsAfterPath >= (hasVisibleScoreThreat || knownAgenda ? 1 : 2) &&
    (hasVisibleScoreThreat || knownAgenda || relevantTrash)
  );
}

function assessRunnerCoveragePressureForMetrics(
  input: AiDecisionInput,
): RunnerCoveragePressureForMetrics {
  const rigCards = input.playerView.own.rig ?? [];
  const gripCards = input.playerView.own.gripOrHq.filter(
    (card) => card.known && card.definitionId,
  );
  const heapCards = input.playerView.own.heapOrArchives.filter(
    (card) => card.known && card.definitionId,
  );
  const missingIceDefinitionIds = new Set<string>();
  const blockedServers = new Set<string>();
  const knownIceBlockedServers = new Set<string>();
  for (const server of input.playerView.servers) {
    if (!runnerStrategicBreakerTargetForMetrics(server)) continue;
    const assessment = assessKnownRezzedIcePath(
      server.ice,
      rigCards,
      input.playerView.own.credits,
      server.root,
    );
    const rezzedMissing = assessment.blocked
      ? server.ice
          .filter(
            (ice) =>
              ice.known &&
              ice.rezzed === true &&
              ice.definitionId &&
              runnerVisibleIceCreatesCoverageNeedForMetrics(ice),
          )
          .map((ice) => ice.definitionId!)
          .filter(
            (definitionId) =>
              !rigCards.some(
                (card) =>
                  card.definitionId &&
                  canBreakerDefinitionBreakIce(card.definitionId, definitionId),
              ),
          )
      : [];
    const knownUnrezzedMissing = server.ice
      .filter(
        (ice) =>
          ice.known &&
          ice.rezzed !== true &&
          ice.definitionId &&
          runnerVisibleIceCreatesCoverageNeedForMetrics(ice),
      )
      .map((ice) => ice.definitionId!)
      .filter(
        (definitionId) =>
          !rigCards.some(
            (card) =>
              card.definitionId &&
              canBreakerDefinitionBreakIce(card.definitionId, definitionId),
          ),
      );
    if (rezzedMissing.length > 0) blockedServers.add(server.id);
    if (knownUnrezzedMissing.length > 0) knownIceBlockedServers.add(server.id);
    for (const definitionId of [...rezzedMissing, ...knownUnrezzedMissing])
      missingIceDefinitionIds.add(definitionId);
  }
  const missingBreakerRoles = new Set(
    [...missingIceDefinitionIds].flatMap(runnerMissingBreakerRolesForMetrics),
  );
  const matchingGripIds = new Set(
    gripCards
      .filter((card) =>
        [...missingIceDefinitionIds].some((iceDefinitionId) =>
          canBreakerDefinitionBreakIce(card.definitionId!, iceDefinitionId),
        ),
      )
      .map((card) => card.instanceId),
  );
  const heapMatchingBreakerCount = heapCards.filter((card) =>
    [...missingIceDefinitionIds].some((iceDefinitionId) =>
      canBreakerDefinitionBreakIce(card.definitionId!, iceDefinitionId),
    ),
  ).length;
  const matchingInstallActionIds = new Set(
    input.legalActions
      .filter(
        (candidate) =>
          candidate.type === "install_card" &&
          typeof candidate.source === "string" &&
          matchingGripIds.has(candidate.source),
      )
      .map((candidate) => candidate.actionId),
  );
  const searchActionIds = new Set(
    input.legalActions
      .filter((candidate) =>
        runnerCoverageSearchActionForMetrics(input, candidate),
      )
      .map((candidate) => candidate.actionId),
  );
  const recoveryActionIds = new Set(
    input.legalActions
      .filter((candidate) =>
        runnerCoverageRecoveryActionForMetrics(input, candidate),
      )
      .filter(() => heapMatchingBreakerCount > 0)
      .map((candidate) => candidate.actionId),
  );
  return {
    blockedServers,
    knownIceBlockedServers,
    missingBreakerRoles,
    matchingInstallActionIds,
    searchActionIds,
    recoveryActionIds,
    heapMatchingBreakerCount,
  };
}

function runnerStrategicBreakerTargetForMetrics(
  server: AiDecisionInput["playerView"]["servers"][number],
): boolean {
  if (server.id === "rd" || server.id === "hq") return true;
  return isRemoteServerTarget(server.id) && server.root.length > 0;
}

function runnerVisibleIceCreatesCoverageNeedForMetrics(
  ice: Pick<VisibleCard, "definitionId" | "effectiveRunQuote">,
): boolean {
  if (!ice.definitionId) return false;
  if (iceHasEndTheRun(ice.definitionId)) return true;
  return (
    ice.effectiveRunQuote?.subroutines.some((subroutine) => {
      const effect = subroutine.unbrokenRunEffect;
      return (
        effect?.addsFutureEndTheRunSubroutines !== undefined ||
        effect?.increasesFutureBreakCostPerSubroutine !== undefined ||
        effect?.preventsFutureBreaking === true ||
        effect?.causesDamageOrProgramTrash === true ||
        effect?.createsRunLockOrActionTax !== undefined
      );
    }) === true
  );
}

function runnerMissingBreakerRolesForMetrics(definitionId: string): string[] {
  const definition =
    RUNTIME_CARDS[definitionId] ?? DEMO_CARDS_BY_ID[definitionId];
  const subtypes = definition?.subtypes ?? [];
  const roles = new Set<string>();
  if (
    subtypes.some((subtype) => runnerSubtypeKeyForMetrics(subtype) === "wall")
  )
    roles.add("breaker_fracter");
  if (
    subtypes.some(
      (subtype) => runnerSubtypeKeyForMetrics(subtype) === "code_gate",
    )
  )
    roles.add("breaker_decoder");
  if (
    subtypes.some((subtype) => runnerSubtypeKeyForMetrics(subtype) === "sentry")
  )
    roles.add("breaker_killer");
  if (roles.size === 0) roles.add("breaker_generic");
  return [...roles].sort();
}

function runnerSubtypeKeyForMetrics(subtype: string): string {
  return subtype
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
}

function runnerCoverageSearchActionForMetrics(
  input: AiDecisionInput,
  action: LegalAction,
): boolean {
  if (action.side !== "runner") return false;
  if (
    action.type !== "play_event" &&
    action.type !== "resolve_choice" &&
    action.type !== "trigger_ability" &&
    action.type !== "activated_card_ability"
  )
    return false;
  const roles = rolesForAction(input, action);
  const sourceCard =
    typeof action.source === "string"
      ? findVisibleCard(input, action.source)
      : undefined;
  const sourceDefinition = sourceCard?.definitionId
    ? (RUNTIME_CARDS[sourceCard.definitionId] ??
      DEMO_CARDS_BY_ID[sourceCard.definitionId])
    : undefined;
  const mechanics =
    sourceDefinition &&
    "mechanics" in sourceDefinition &&
    Array.isArray(sourceDefinition.mechanics)
      ? sourceDefinition.mechanics
      : [];
  return (
    roles.some(
      (role) =>
        role.includes("search") ||
        role.includes("tutor") ||
        role === "program_search" ||
        role === "stack_search" ||
        role === "search_stack" ||
        role === "search_trash" ||
        role === "setup_search" ||
        role.includes("recovery") ||
        role.includes("trash_recovery"),
    ) ||
    mechanics.some(
      (mechanic: string) =>
        mechanic.includes("search") ||
        mechanic.includes("tutor") ||
        mechanic.includes("hidden_zone_tool"),
    )
  );
}

function runnerCoverageRecoveryActionForMetrics(
  input: AiDecisionInput,
  action: LegalAction,
): boolean {
  const roles = rolesForAction(input, action);
  return roles.some(
    (role) =>
      role.includes("recovery") ||
      role.includes("trash_recovery") ||
      role === "search_trash",
  );
}

function runnerHandUseDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  decision: AiDecision,
  action: LegalAction,
  targetServerId: string | undefined,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "runner" || action.side !== "runner") return {};
  const draw = runnerDrawKindForSimulationAction(input, action);
  const playableEconomy = hasRunnerPlayableEconomyAction(
    input,
    action.actionId,
  );
  const installableBreaker = hasRunnerInstallableBreakerAction(
    input,
    action.actionId,
  );
  const runnablePressure = hasRunnerRunnablePressureAction(
    input,
    action.actionId,
  );
  const remoteTrashAvailable = hasRunnerRemoteTrashAction(input);
  const discardRoles = runnerDiscardChoiceRoles(input, decision);
  const installAction = action.type === "install_card";
  const duplicateInstall =
    installAction && isRunnerDuplicateInstall(input, action);
  const lowValueDuplicate =
    duplicateInstall && isRunnerLowValueDuplicateInstall(input, action);
  const economyActionTaken = isRunnerEconomyAction(input, action);
  const rigInstallAction =
    installAction && isRunnerRigInstallAction(input, action);
  const pressureActionTaken = isRunnerPressureAction(input, action);
  const remoteTrashTaken =
    action.type === "trash_accessed_card" &&
    isRemoteServerTarget(
      targetServerId ?? input.playerView.run?.attackedServerId,
    );
  const remoteTrash = runnerRemoteTrashAccessContext(input, action);
  const advancedRemoteContest = runnerAdvancedRemoteContestContext(
    input,
    action,
    targetServerId,
  );
  const handUseOpportunity =
    playableEconomy ||
    installableBreaker ||
    runnablePressure ||
    remoteTrashAvailable;
  const handUseActionTaken =
    economyActionTaken ||
    rigInstallAction ||
    pressureActionTaken ||
    remoteTrashTaken;

  return {
    ...(draw.draw ? { runnerDrawAction: true } : {}),
    ...(draw.click ? { runnerClickDrawAction: true } : {}),
    ...(draw.cardEffect ? { runnerCardEffectDrawAction: true } : {}),
    ...(draw.draw && playableEconomy
      ? { runnerDrawWhileHoldingPlayableEconomy: true }
      : {}),
    ...(draw.draw && installableBreaker
      ? { runnerDrawWhileHoldingInstallableBreaker: true }
      : {}),
    ...(draw.draw && runnablePressure
      ? { runnerDrawWhileHoldingRunnablePressureCard: true }
      : {}),
    ...(draw.draw && remoteTrashAvailable
      ? { runnerDrawWhileRemoteTrashAvailable: true }
      : {}),
    ...(discardRoles.length > 0 ? { runnerDiscardChoice: true } : {}),
    ...(discardRoles.some((role) => isRunnerEconomyRole(role))
      ? { runnerDiscardedPlayableEconomy: true }
      : {}),
    ...(discardRoles.some((role) => role.startsWith("breaker_"))
      ? { runnerDiscardedInstallableBreaker: true }
      : {}),
    ...(discardRoles.some((role) => isRunnerPressureRole(role))
      ? { runnerDiscardedRunPressureCard: true }
      : {}),
    ...(installAction ? { runnerInstallAction: true } : {}),
    ...(duplicateInstall ? { runnerDuplicateInstallAction: true } : {}),
    ...(lowValueDuplicate
      ? { runnerLowValueDuplicateInstallAction: true }
      : {}),
    ...(duplicateInstall &&
    sourceDefinitionIdForSimulationAction(input, action) ===
      "onr_v1_165_junkyard-bbs"
      ? { runnerJunkyardBbsDuplicateInstall: true }
      : {}),
    ...(economyActionTaken ? { runnerEconomyActionTaken: true } : {}),
    ...(rigInstallAction ? { runnerRigInstallAction: true } : {}),
    ...(pressureActionTaken ? { runnerPressureActionTaken: true } : {}),
    ...(remoteTrashAvailable ? { runnerRemoteTrashOpportunity: true } : {}),
    ...(remoteTrashTaken ? { runnerRemoteTrashTaken: true } : {}),
    ...(remoteTrash.trashable
      ? { runnerRemoteAccessWithTrashableCard: true }
      : {}),
    ...(remoteTrash.relevant
      ? { runnerRemoteAccessWithRelevantTrashableCard: true }
      : {}),
    ...(remoteTrash.affordableRelevant
      ? { runnerAffordableRelevantRemoteTrashOpportunity: true }
      : {}),
    ...(remoteTrash.relevantTaken
      ? { runnerRelevantRemoteTrashTaken: true }
      : {}),
    ...(remoteTrash.skippedAffordableRelevant
      ? { runnerSkippedAffordableRelevantRemoteTrash: true }
      : {}),
    ...(remoteTrash.targetType
      ? { runnerRemoteTrashTargetType: remoteTrash.targetType }
      : {}),
    ...(remoteTrash.role ? { runnerRemoteTrashRole: remoteTrash.role } : {}),
    ...(remoteTrash.trashable && action.type === "decline_trash"
      ? { runnerRemoteTrashDeclined: true }
      : {}),
    ...(remoteTrash.trashable
      ? {
          runnerRemoteTrashCost: remoteTrash.trashCost,
          runnerRemoteTrashCostBucket: remoteTrashCostBucket(
            remoteTrash.trashCost,
          ),
          runnerRemoteTrashLegalActionCount: remoteTrash.legalTrashActionCount,
        }
      : {}),
    ...(remoteTrash.role === "economy"
      ? { runnerRemoteTrashAssetEconomy: true }
      : {}),
    ...(remoteTrash.finitePoolEconomy
      ? { runnerRemoteTrashFinitePoolEconomy: true }
      : {}),
    ...(remoteTrash.corpValueRemaining > 0
      ? { runnerRemoteTrashCorpValueRemaining: remoteTrash.corpValueRemaining }
      : {}),
    ...(remoteTrash.bbsWhisperingCampaign
      ? { runnerBbsWhisperingCampaignAccessed: true }
      : {}),
    ...(remoteTrash.bbsWhisperingCampaign &&
    remoteTrash.legalTrashActionCount > 0
      ? { runnerBbsWhisperingCampaignTrashLegal: true }
      : {}),
    ...(remoteTrash.bbsWhisperingCampaign && remoteTrashTaken
      ? { runnerBbsWhisperingCampaignTrashTaken: true }
      : {}),
    ...(remoteTrash.bbsWhisperingCampaign && action.type === "decline_trash"
      ? { runnerBbsWhisperingCampaignTrashSkipped: true }
      : {}),
    ...(remoteTrash.bbsWhisperingCampaign &&
    remoteTrash.skippedAffordableRelevant
      ? { runnerBbsWhisperingCampaignTrashSkippedAffordable: true }
      : {}),
    ...(remoteTrash.finitePoolEconomy
      ? { runnerFinitePoolAssetAccessed: true }
      : {}),
    ...(remoteTrash.finitePoolEconomy && remoteTrash.legalTrashActionCount > 0
      ? { runnerFinitePoolAssetTrashLegal: true }
      : {}),
    ...(remoteTrash.finitePoolEconomy && remoteTrashTaken
      ? { runnerFinitePoolAssetTrashTaken: true }
      : {}),
    ...(remoteTrash.finitePoolEconomy && remoteTrash.skippedAffordableRelevant
      ? { runnerFinitePoolAssetTrashSkippedAffordable: true }
      : {}),
    ...(remoteTrash.skippedAffordableRelevant
      ? { runnerRemoteTrashFixGateEligible: true }
      : {}),
    ...(remoteTrash.deferredByBudget
      ? { runnerRemoteTrashFixGateBlockedByReserve: true }
      : {}),
    ...(remoteTrash.trashable &&
    remoteTrash.legalTrashActionCount === 0 &&
    input.playerView.own.credits < remoteTrash.trashCost
      ? { runnerRemoteTrashFixGateBlockedByLowCredits: true }
      : {}),
    ...(remoteTrash.skippedAffordableRelevant && action.type === "steal_agenda"
      ? { runnerRemoteTrashFixGateBlockedByHigherThreat: true }
      : {}),
    ...(remoteTrash.skippedAffordableRelevant &&
    action.type !== "steal_agenda" &&
    !remoteTrash.deferredByBudget
      ? { runnerRemoteTrashFixGateSuspicious: true }
      : {}),
    ...(remoteTrash.expensive
      ? { runnerExpensiveRemoteTrashOpportunity: true }
      : {}),
    ...(remoteTrash.expensive && remoteTrashTaken
      ? { runnerExpensiveRemoteTrashTaken: true }
      : {}),
    ...(remoteTrash.expensive &&
    remoteTrash.trashable &&
    action.type === "decline_trash"
      ? { runnerExpensiveRemoteTrashDeclined: true }
      : {}),
    ...(remoteTrash.highImpact && remoteTrashTaken
      ? { runnerHighImpactRemoteTrashTaken: true }
      : {}),
    ...(remoteTrash.deferredByBudget
      ? { runnerHighImpactRemoteTrashDeferredByBudget: true }
      : {}),
    ...(remoteTrash.highImpact &&
    remoteTrash.expensive &&
    !remoteTrash.acuteThreat &&
    action.type === "decline_trash"
      ? { runnerHighImpactRemoteTrashSkippedNoThreat: true }
      : {}),
    ...(remoteTrash.role === "low_value" && action.type === "decline_trash"
      ? { runnerLowValueRemoteTrashSkipped: true }
      : {}),
    ...(remoteTrashTaken && input.actionNumber <= 20
      ? { runnerRemoteTrashSpentEarlyGame: true }
      : {}),
    ...(remoteTrashTaken
      ? {
          runnerCreditsAfterRemoteTrash: remoteTrash.creditsAfterGeneralTrash,
          dedicatedTrashCreditsUsed: remoteTrash.dedicatedTrashCredits,
          generalCreditsSpentOnTrash: remoteTrash.generalCreditCost,
        }
      : {}),
    ...(remoteTrashTaken && remoteTrash.dropsBelowReserve
      ? { runnerRemoteTrashDroppedBelowReserve: true }
      : {}),
    ...(remoteTrashTaken && !remoteTrash.dropsBelowReserve
      ? { runnerRemoteTrashPreservedReserve: true }
      : {}),
    ...(remoteTrashTaken && remoteTrash.acuteThreat
      ? { runnerRemoteTrashProtectedScoreThreat: true }
      : {}),
    ...(remoteTrashTaken && !remoteTrash.acuteThreat
      ? { runnerRemoteTrashWithoutImmediateThreat: true }
      : {}),
    ...(remoteTrashTaken &&
    remoteTrash.dropsBelowReserve &&
    !remoteTrash.acuteThreat
      ? { trashDecisionLeftRunnerUnableToContest: true }
      : {}),
    ...(advancedRemoteContest.opportunity
      ? { runnerRemoteRunOpportunityAgainstAdvancedRemote: true }
      : {}),
    ...(advancedRemoteContest.taken
      ? { runnerRemoteRunAgainstAdvancedRemote: true }
      : {}),
    ...(advancedRemoteContest.skipped
      ? { runnerSkippedAdvancedRemoteContest: true }
      : {}),
    ...(advancedRemoteContest.centralWhileThreat
      ? { runnerCentralRunWhileRemoteScoreThreatVisible: true }
      : {}),
    ...(typeof advancedRemoteContest.reserveAfterRun === "number"
      ? {
          runnerRemoteContestCreditReserveAfterRun:
            advancedRemoteContest.reserveAfterRun,
        }
      : {}),
    ...(handUseOpportunity ? { runnerHandUseOpportunity: true } : {}),
    ...(handUseActionTaken ? { runnerHandUseActionTaken: true } : {}),
  };
}

type RunnerEconomySetupActionClass = {
  economy: boolean;
  burstEconomy: boolean;
  actionEconomy: boolean;
  finitePoolEconomy: boolean;
  loanDebtEconomy: boolean;
  recurringEconomy: boolean;
  resourceEconomy: boolean;
  hardwareEconomy: boolean;
  memoryHardware: boolean;
  handSizeSupport: boolean;
  search: boolean;
  recovery: boolean;
  downsideEconomy: boolean;
  delayedPenaltyEconomy: boolean;
};

type RunnerSetupMissingCoverageType =
  | "wall"
  | "code_gate"
  | "sentry"
  | "universal"
  | "special";

function runnerEconomySetupDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
  stateAfterAction: GameState,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "runner" || action.side !== "runner") return {};
  const legalRunnerActions = input.legalActions.filter(
    (candidate) => candidate.side === "runner",
  );
  const classified = legalRunnerActions.map((candidate) => ({
    action: candidate,
    classification: runnerEconomySetupActionClass(input, candidate),
  }));
  const legalEconomy = classified.filter(
    ({ classification }) => classification.economy,
  );
  const legalMemory = classified.filter(
    ({ classification }) => classification.memoryHardware,
  );
  const legalHandSize = classified.filter(
    ({ classification }) => classification.handSizeSupport,
  );
  const legalSearch = classified.filter(
    ({ classification }) => classification.search,
  );
  const legalRecovery = classified.filter(
    ({ classification }) => classification.recovery,
  );
  const chosen = runnerEconomySetupActionClass(input, action);
  const economyWindow = legalEconomy.length > 0;
  const economyTaken = economyWindow && chosen.economy;
  const economySkipped = economyWindow && !economyTaken;
  const reserveTarget = runnerCreditReserveTargetForInput(input);
  const creditsBefore = input.playerView.own.credits;
  const creditsAfter = stateAfterAction.runner.credits;
  const lowCredits = creditsBefore < reserveTarget;
  const knownUnaffordablePath = runnerHasKnownUnaffordableLegalRun(input);
  const advancedRemoteContest = runnerAdvancedRemoteContestContext(
    input,
    action,
    targetServerId,
  );
  const freshPressureAvailable = hasRunnerRunnablePressureAction(
    input,
    action.actionId,
  );
  const installableBreaker = hasRunnerInstallableBreakerAction(
    input,
    action.actionId,
  );
  const remoteTrashAvailable = hasRunnerRemoteTrashAction(input);
  const draw = runnerDrawKindForSimulationAction(input, action).draw;
  const runAction = action.type === "start_run";
  const setupAction =
    action.type === "install_card" &&
    (isRunnerRigInstallAction(input, action) || installableBreaker);
  const relevantSkippedReason = economySkipped
    ? runnerEconomySkipReasonForDiagnostics({
        action,
        draw,
        runAction,
        setupAction,
        installableBreaker,
        remoteTrashAvailable,
        advancedRemoteContestSkipped: advancedRemoteContest.skipped,
        freshPressureAvailable,
      })
    : undefined;
  const rich = creditsBefore >= Math.max(8, reserveTarget + 3);
  const economyNeeded = lowCredits || knownUnaffordablePath;
  const economyReserveSetup =
    economyTaken &&
    creditsBefore < reserveTarget &&
    creditsAfter >= reserveTarget;
  const economyStillBelowReserve = economyTaken && creditsAfter < reserveTarget;
  const finiteSeen = legalEconomy.some(
    ({ classification }) => classification.finitePoolEconomy,
  );
  const finiteTaken = economyTaken && chosen.finitePoolEconomy;
  const debtSeen = legalEconomy.some(
    ({ classification }) => classification.loanDebtEconomy,
  );
  const debtTaken = economyTaken && chosen.loanDebtEconomy;
  const downsideSeen = legalEconomy.some(
    ({ classification }) => classification.downsideEconomy,
  );
  const downsideTaken = economyTaken && chosen.downsideEconomy;
  const memoryWindow = legalMemory.length > 0;
  const handSizeWindow = legalHandSize.length > 0;
  const missingBreakerCoverage =
    runnerVisibleMissingBreakerCoverage(input) ||
    runnerHasKnownBlockedPathByCoverage(input);
  const missingCoverageTypes = runnerMissingCoverageTypesForInput(input);
  const legalProgramInstalls = legalRunnerActions.filter((candidate) => {
    if (candidate.type !== "install_card") return false;
    const definition = definitionForSimulationAction(input, candidate);
    return definition?.type === "program";
  }).length;
  const handSizeNeedVisible =
    (input.playerView.own.tags ?? 0) > 0 ||
    (input.playerView.own.gripOrHq?.length ?? 0) >
      Math.max(0, input.playerView.own.maxHandSize ?? 5);
  const memorySkipped = memoryWindow && !chosen.memoryHardware;
  const handSizeSkipped = handSizeWindow && !chosen.handSizeSupport;
  const searchTaken = chosen.search;
  const recoveryTaken = chosen.recovery;
  const searchSkippedWithCoverage =
    legalSearch.length > 0 && !searchTaken && missingBreakerCoverage;
  const recoverySkippedWithCoverage =
    legalRecovery.length > 0 && !recoveryTaken && missingBreakerCoverage;
  const economyOverPressure = economyTaken && freshPressureAvailable;
  const economyOverRemoteContest =
    economyTaken && advancedRemoteContest.skipped;
  const economyOverSetup = economyTaken && installableBreaker;
  const economyOverTrash = economyTaken && remoteTrashAvailable;
  const economyPlausible =
    economyTaken &&
    (economyNeeded || economyReserveSetup || creditsAfter < reserveTarget + 2);
  const economySuspicious =
    economyTaken &&
    !economyPlausible &&
    ((rich && (freshPressureAvailable || advancedRemoteContest.opportunity)) ||
      economyOverRemoteContest ||
      economyOverTrash ||
      (debtTaken && !economyNeeded));
  const suspiciousEconomyOverPressure =
    economyOverPressure && !economyPlausible && (rich || !economyNeeded);
  const suspiciousEconomyOverRemoteContest =
    economyOverRemoteContest && !economyPlausible && (rich || !economyNeeded);
  const classifications = sortedUnique([
    ...(economyWindow ? ["runner_economy_window"] : []),
    ...(economyTaken ? ["runner_economy_taken"] : []),
    ...(economySkipped ? ["runner_economy_skipped"] : []),
    ...(finiteSeen ? ["finite_pool_economy_seen"] : []),
    ...(debtSeen ? ["debt_economy_seen"] : []),
    ...(memoryWindow ? ["memory_hardware_window"] : []),
    ...(handSizeWindow ? ["hand_size_window"] : []),
    ...(legalSearch.length > 0 ? ["search_window"] : []),
    ...(legalRecovery.length > 0 ? ["recovery_window"] : []),
    ...(economySuspicious ? ["economy_choice_suspicious"] : []),
    ...(economyPlausible ? ["economy_choice_plausible"] : []),
  ]);
  const evidence = sortedUnique([
    `runner_credits:${creditsBefore}`,
    `runner_reserve_target:${reserveTarget}`,
    `legal_economy_actions:${legalEconomy.length}`,
    `legal_memory_hardware_actions:${legalMemory.length}`,
    `legal_hand_size_actions:${legalHandSize.length}`,
    `legal_search_actions:${legalSearch.length}`,
    `legal_recovery_actions:${legalRecovery.length}`,
    `known_unaffordable_path:${knownUnaffordablePath}`,
    `missing_breaker_coverage:${missingBreakerCoverage}`,
    ...(chosen.handSizeSupport
      ? ["mram_militech_classified_as_hand_size:true"]
      : []),
  ]);

  return {
    ...(economyWindow ? { runnerEconomyDecisionWindow: true } : {}),
    ...(legalEconomy.length > 0
      ? { runnerLegalEconomyActions: legalEconomy.length }
      : {}),
    ...runnerEconomySubcounts(
      legalEconomy.map((entry) => entry.classification),
    ),
    ...(economyTaken ? { runnerEconomyTaken: true } : {}),
    ...(economySkipped ? { runnerEconomySkipped: true } : {}),
    ...(economySkipped && lowCredits
      ? { runnerEconomySkippedWhileLowCredits: true }
      : {}),
    ...(economySkipped && knownUnaffordablePath
      ? { runnerEconomySkippedWhileKnownUnaffordablePath: true }
      : {}),
    ...(relevantSkippedReason === "pressure"
      ? { runnerEconomySkippedForPressure: true }
      : {}),
    ...(relevantSkippedReason === "remote_contest"
      ? { runnerEconomySkippedForRemoteContest: true }
      : {}),
    ...(relevantSkippedReason === "setup"
      ? { runnerEconomySkippedForSetup: true }
      : {}),
    ...(relevantSkippedReason === "draw"
      ? { runnerEconomySkippedForDraw: true }
      : {}),
    ...(relevantSkippedReason === "run"
      ? { runnerEconomySkippedForRun: true }
      : {}),
    ...(relevantSkippedReason === "install_breaker"
      ? { runnerEconomySkippedForInstallBreaker: true }
      : {}),
    ...(relevantSkippedReason === "trash"
      ? { runnerEconomySkippedForTrash: true }
      : {}),
    ...(relevantSkippedReason === "end_turn"
      ? { runnerEconomySkippedForEndTurn: true }
      : {}),
    ...(relevantSkippedReason === "unknown_higher_priority"
      ? { runnerEconomySkippedForUnknownHigherPriority: true }
      : {}),
    ...(lowCredits ? { runnerLowCreditDecisionWindow: true } : {}),
    ...(economyWindow && lowCredits
      ? { runnerCreditStarvedWithLegalEconomy: true }
      : {}),
    ...(economyTaken && lowCredits
      ? { runnerCreditStarvedEconomyTaken: true }
      : {}),
    ...(economySkipped && lowCredits
      ? { runnerCreditStarvedEconomySkipped: true }
      : {}),
    ...(economyWindow && knownUnaffordablePath
      ? { runnerKnownUnaffordablePathWithLegalEconomy: true }
      : {}),
    ...(economyReserveSetup
      ? { runnerEconomyTakenToReachRunReserve: true }
      : {}),
    ...(economyStillBelowReserve
      ? { runnerEconomyTakenButStillBelowReserve: true }
      : {}),
    ...(economySkipped && knownUnaffordablePath
      ? {
          runnerEconomySkippedThenUnaffordableRun: true,
          runnerRunStartedAfterSkippingEconomy: runAction,
        }
      : {}),
    ...(runAction &&
    runnerRunKnownPathCost(input, targetServerId) > creditsBefore
      ? { runnerRunStartedBelowKnownPathCost: true }
      : {}),
    ...(economyOverPressure
      ? { runnerEconomyChosenOverFreshCentralPressure: true }
      : {}),
    ...(economyOverRemoteContest
      ? { runnerEconomyChosenOverRemoteContest: true }
      : {}),
    ...(economyOverSetup
      ? { runnerEconomyChosenOverBreakerInstall: true }
      : {}),
    ...(economyOverSetup ? { runnerEconomyChosenOverCriticalSetup: true } : {}),
    ...(economyOverTrash ? { runnerEconomyChosenOverRelevantTrash: true } : {}),
    ...(economyTaken && rich ? { runnerEconomyChosenWhileRich: true } : {}),
    ...(economyTaken && freshPressureAvailable
      ? { runnerEconomyChosenWhilePressureReady: true }
      : {}),
    ...(economyReserveSetup ? { runnerEconomyChosenAsReserveSetup: true } : {}),
    ...(economyPlausible ? { runnerEconomyChoicePlausible: true } : {}),
    ...(economySuspicious ? { runnerEconomyChoiceSuspicious: true } : {}),
    ...(finiteSeen ? { runnerFinitePoolEconomySeen: true } : {}),
    ...(finiteTaken ? { runnerFinitePoolEconomyTaken: true } : {}),
    ...(finiteSeen && economySkipped
      ? { runnerFinitePoolEconomySkipped: true }
      : {}),
    ...(debtSeen ? { runnerDebtEconomySeen: true } : {}),
    ...(debtTaken ? { runnerDebtEconomyTaken: true } : {}),
    ...(debtSeen && economySkipped ? { runnerDebtEconomySkipped: true } : {}),
    ...(debtTaken && !economyNeeded
      ? { runnerDebtEconomyTakenWithoutNeed: true }
      : {}),
    ...(downsideSeen ? { runnerEconomyWithDownsideSeen: true } : {}),
    ...(downsideTaken ? { runnerEconomyWithDownsideTaken: true } : {}),
    ...(chosen.delayedPenaltyEconomy
      ? { runnerDelayedPenaltyEconomyTaken: true }
      : {}),
    ...(memoryWindow ? { runnerMemoryBottleneckDecisionWindow: true } : {}),
    ...(handSizeWindow ? { runnerHandSizeBottleneckDecisionWindow: true } : {}),
    ...(legalMemory.length > 0
      ? { runnerLegalMemoryHardwareActions: legalMemory.length }
      : {}),
    ...(legalHandSize.length > 0
      ? { runnerLegalHandSizeActions: legalHandSize.length }
      : {}),
    ...(chosen.memoryHardware ? { runnerMemoryHardwareTaken: true } : {}),
    ...(chosen.handSizeSupport
      ? {
          runnerHandSizeSupportTaken: true,
          runnerHandSizeFactUsedForDiagnosis: true,
        }
      : {}),
    ...(memorySkipped && legalProgramInstalls > 0
      ? { runnerMemorySupportSkippedWhileGripHasPrograms: true }
      : {}),
    ...(handSizeSkipped && handSizeNeedVisible
      ? { runnerHandSizeSupportSkippedWhileDamageRiskVisible: true }
      : {}),
    ...(chosen.memoryHardware || chosen.handSizeSupport
      ? {
          ...(economyWindow && !economyTaken
            ? { runnerHardwareSetupChosenOverEconomy: true }
            : {}),
          ...(freshPressureAvailable
            ? { runnerHardwareSetupChosenOverPressure: true }
            : {}),
        }
      : {}),
    ...(legalSearch.length > 0
      ? { runnerLegalSearchActions: legalSearch.length }
      : {}),
    ...(legalRecovery.length > 0
      ? { runnerLegalRecoveryActions: legalRecovery.length }
      : {}),
    ...(searchTaken ? { runnerSearchTaken: true } : {}),
    ...(recoveryTaken ? { runnerRecoveryTaken: true } : {}),
    ...(searchSkippedWithCoverage
      ? { runnerSearchSkippedWhileMissingBreakerCoverage: true }
      : {}),
    ...(recoverySkippedWithCoverage
      ? { runnerRecoverySkippedWhileMissingBreakerCoverage: true }
      : {}),
    ...(searchTaken && missingBreakerCoverage
      ? { runnerSearchTakenForBreakerCoverage: true }
      : {}),
    ...(recoveryTaken && missingBreakerCoverage
      ? { runnerRecoveryTakenForBreakerCoverage: true }
      : {}),
    ...((searchTaken || recoveryTaken) && economyWindow && !economyTaken
      ? { runnerSearchRecoveryChosenOverEconomy: true }
      : {}),
    ...((searchTaken || recoveryTaken) && freshPressureAvailable
      ? { runnerSearchRecoveryChosenOverPressure: true }
      : {}),
    ...(economySkipped && lowCredits && knownUnaffordablePath
      ? { runnerEconomyFixGateEligibleStarvedSkip: true }
      : {}),
    ...(economyTaken && rich
      ? { runnerEconomyFixGateSuspiciousRichEconomy: true }
      : {}),
    ...(suspiciousEconomyOverPressure
      ? { runnerEconomyFixGateSuspiciousEconomyOverPressure: true }
      : {}),
    ...(suspiciousEconomyOverRemoteContest
      ? { runnerEconomyFixGateSuspiciousEconomyOverRemoteContest: true }
      : {}),
    ...(debtTaken && !economyNeeded
      ? { runnerEconomyFixGateSuspiciousDebtEconomyWithoutNeed: true }
      : {}),
    ...(memorySkipped && legalProgramInstalls > 0
      ? { runnerSetupFixGateEligibleMemorySkip: true }
      : {}),
    ...(searchSkippedWithCoverage || recoverySkippedWithCoverage
      ? { runnerSetupFixGateEligibleSearchRecoverySkip: true }
      : {}),
    ...(missingCoverageTypes.length > 0
      ? { runnerSetupMissingCoverageTypes: missingCoverageTypes }
      : {}),
    ...(economySkipped || searchSkippedWithCoverage || memorySkipped
      ? {
          runnerSetupAttributionEvidence: sortedUnique([
            `chosen_action_type:${action.type}`,
            `chosen_reason_family:${runnerSetupChosenFamilyForEntry({
              actionType: action.type,
              runnerEconomyTaken: chosen.economy,
              runnerDrawAction: draw,
              runnerRigInstallAction: setupAction,
              runnerSearchTaken: searchTaken,
              runnerRecoveryTaken: recoveryTaken,
              runnerRemoteTrashTaken: action.type === "trash_accessed_card",
            })}`,
            `runner_credits:${creditsBefore}`,
            `reserve_target:${reserveTarget}`,
            `known_path_affordable:${!knownUnaffordablePath}`,
            `missing_coverage_types:${missingCoverageTypes.join(",") || "none"}`,
          ]),
        }
      : {}),
    ...(classifications.length > 0
      ? { runnerEconomySetupClassifications: classifications }
      : {}),
    ...(classifications.length > 0
      ? { runnerEconomySetupEvidence: evidence }
      : {}),
  };
}

function runnerEconomySubcounts(
  classifications: RunnerEconomySetupActionClass[],
): Partial<AiSimulationSummary["actionSequence"][number]> {
  const count = (
    selector: (classification: RunnerEconomySetupActionClass) => boolean,
  ) => classifications.filter(selector).length;
  return {
    ...(count((classification) => classification.burstEconomy) > 0
      ? {
          runnerLegalBurstEconomyActions: count(
            (classification) => classification.burstEconomy,
          ),
        }
      : {}),
    ...(count((classification) => classification.actionEconomy) > 0
      ? {
          runnerLegalActionEconomyActions: count(
            (classification) => classification.actionEconomy,
          ),
        }
      : {}),
    ...(count((classification) => classification.finitePoolEconomy) > 0
      ? {
          runnerLegalFinitePoolEconomyActions: count(
            (classification) => classification.finitePoolEconomy,
          ),
        }
      : {}),
    ...(count((classification) => classification.loanDebtEconomy) > 0
      ? {
          runnerLegalLoanDebtEconomyActions: count(
            (classification) => classification.loanDebtEconomy,
          ),
        }
      : {}),
    ...(count((classification) => classification.recurringEconomy) > 0
      ? {
          runnerLegalRecurringEconomyActions: count(
            (classification) => classification.recurringEconomy,
          ),
        }
      : {}),
    ...(count((classification) => classification.resourceEconomy) > 0
      ? {
          runnerLegalResourceEconomyActions: count(
            (classification) => classification.resourceEconomy,
          ),
        }
      : {}),
    ...(count((classification) => classification.hardwareEconomy) > 0
      ? {
          runnerLegalHardwareEconomyActions: count(
            (classification) => classification.hardwareEconomy,
          ),
        }
      : {}),
  };
}

function runnerEconomySetupActionClass(
  input: AiDecisionInput,
  action: LegalAction,
): RunnerEconomySetupActionClass {
  const definitionId = sourceDefinitionIdForSimulationAction(input, action);
  const definition = definitionForSimulationAction(input, action);
  const roles = rolesForAction(input, action);
  const mechanics =
    definition &&
    "mechanics" in definition &&
    Array.isArray(definition.mechanics)
      ? definition.mechanics
      : [];
  const isShortTermContract = definitionId === "onr_v1_178_short-term-contract";
  const isLoanFromChiba = definitionId === "onr_v1_168_loan-from-chiba";
  const isMramHandSize =
    definitionId === "onr_v1_133_militech-mram-chip" ||
    definitionId === "onr_v1_134_mram-chip";
  const economy = isRunnerEconomyAction(input, action);
  const search = runnerCoverageSearchActionForMetrics(input, action);
  const recovery = runnerCoverageRecoveryActionForMetrics(input, action);
  const handSizeSupport =
    isMramHandSize ||
    roles.some(
      (role) =>
        role.includes("hand_size") ||
        role.includes("damage_resilience") ||
        role.includes("damage_prevention"),
    ) ||
    mechanics.some(
      (mechanic: string) =>
        mechanic.includes("hand") || mechanic.includes("damage_prevention"),
    );
  const memoryHardware =
    !handSizeSupport &&
    action.type === "install_card" &&
    (roles.includes("memory") ||
      roles.includes("memory_support") ||
      mechanics.some((mechanic: string) => mechanic.includes("memory")));
  return {
    economy,
    burstEconomy: economy && action.type === "play_event",
    actionEconomy:
      economy &&
      (action.type === "gain_credit" ||
        action.type === "trigger_ability" ||
        action.type === "activated_card_ability"),
    finitePoolEconomy:
      economy &&
      (isShortTermContract ||
        roles.some(
          (role) => role.includes("finite") || role.includes("pool"),
        ) ||
        mechanics.some(
          (mechanic: string) =>
            mechanic.includes("counter") ||
            mechanic.includes("resource_action"),
        )),
    loanDebtEconomy:
      economy &&
      (isLoanFromChiba ||
        roles.some((role) => role.includes("loan") || role.includes("debt"))),
    recurringEconomy:
      economy &&
      roles.some((role) => role.includes("recurring") || role.includes("drip")),
    resourceEconomy: economy && definition?.type === "resource",
    hardwareEconomy: economy && definition?.type === "hardware",
    memoryHardware,
    handSizeSupport,
    search,
    recovery,
    downsideEconomy:
      economy &&
      (isLoanFromChiba ||
        roles.some(
          (role) =>
            role.includes("risk") ||
            role.includes("downside") ||
            role.includes("penalty") ||
            role.includes("tag"),
        )),
    delayedPenaltyEconomy:
      economy &&
      (isLoanFromChiba ||
        roles.some(
          (role) => role.includes("delayed") || role.includes("penalty"),
        )),
  };
}

function definitionForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
) {
  const definitionId = sourceDefinitionIdForSimulationAction(input, action);
  return definitionId
    ? (RUNTIME_CARDS[definitionId] ?? DEMO_CARDS_BY_ID[definitionId])
    : undefined;
}

function runnerEconomySkipReasonForDiagnostics(context: {
  action: LegalAction;
  draw: boolean;
  runAction: boolean;
  setupAction: boolean;
  installableBreaker: boolean;
  remoteTrashAvailable: boolean;
  advancedRemoteContestSkipped: boolean;
  freshPressureAvailable: boolean;
}):
  | "pressure"
  | "remote_contest"
  | "setup"
  | "draw"
  | "run"
  | "install_breaker"
  | "trash"
  | "end_turn"
  | "unknown_higher_priority" {
  if (context.advancedRemoteContestSkipped) return "remote_contest";
  if (
    context.action.type === "trash_accessed_card" ||
    context.remoteTrashAvailable
  )
    return "trash";
  if (context.installableBreaker && context.action.type === "install_card")
    return "install_breaker";
  if (context.setupAction) return "setup";
  if (context.draw) return "draw";
  if (context.runAction && context.freshPressureAvailable) return "pressure";
  if (context.runAction) return "run";
  if (context.action.type === "end_turn") return "end_turn";
  return "unknown_higher_priority";
}

function runnerHasKnownUnaffordableLegalRun(input: AiDecisionInput): boolean {
  return input.legalActions.some((action) => {
    if (
      action.side !== "runner" ||
      action.type !== "start_run" ||
      typeof action.payload?.serverId !== "string"
    )
      return false;
    return (
      runnerRunKnownPathCost(input, action.payload.serverId) >
      input.playerView.own.credits
    );
  });
}

function runnerRunKnownPathCost(
  input: AiDecisionInput,
  targetServerId: string | undefined,
): number {
  if (!targetServerId) return 0;
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === targetServerId,
  );
  if (!server) return 0;
  return (
    assessKnownRezzedIcePath(
      server.ice,
      input.playerView.own.rig ?? [],
      input.playerView.own.credits,
      server.root,
    ).visibleBreakCost ?? 0
  );
}

function runnerVisibleMissingBreakerCoverage(input: AiDecisionInput): boolean {
  const rigRoles = new Set(
    (input.playerView.own.rig ?? []).flatMap((card) =>
      rolesForCardId(card.definitionId),
    ),
  );
  return input.playerView.servers.some((server) =>
    server.ice
      .filter(
        (ice): ice is typeof ice & { definitionId: string } =>
          ice.known && typeof ice.definitionId === "string",
      )
      .flatMap((ice) => runnerMissingBreakerRolesForMetrics(ice.definitionId))
      .some((role) => !rigRoles.has(role)),
  );
}

function runnerMissingCoverageTypesForInput(
  input: AiDecisionInput,
): RunnerSetupMissingCoverageType[] {
  const rigRoles = new Set(
    (input.playerView.own.rig ?? []).flatMap((card) =>
      rolesForCardId(card.definitionId),
    ),
  );
  const missing = new Set<RunnerSetupMissingCoverageType>();
  for (const server of input.playerView.servers) {
    for (const ice of server.ice) {
      if (!ice.known || typeof ice.definitionId !== "string") continue;
      for (const role of runnerMissingBreakerRolesForMetrics(
        ice.definitionId,
      )) {
        if (rigRoles.has(role)) continue;
        if (role === "breaker_fracter") missing.add("wall");
        else if (role === "breaker_decoder") missing.add("code_gate");
        else if (role === "breaker_killer") missing.add("sentry");
        else missing.add("universal");
      }
      if (
        ice.effectiveRunQuote?.subroutines.some(
          (subroutine) =>
            String(subroutine.type).includes("trace") ||
            String(subroutine.type).includes("damage"),
        ) === true
      )
        missing.add("special");
    }
  }
  return [...missing].sort();
}

function runnerHasKnownBlockedPathByCoverage(input: AiDecisionInput): boolean {
  return input.playerView.servers.some(
    (server) =>
      assessKnownRezzedIcePath(
        server.ice,
        input.playerView.own.rig ?? [],
        input.playerView.own.credits,
        server.root,
      ).blocked,
  );
}

function runnerCentralPressureDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "runner" || action.side !== "runner") return {};
  const centralTarget = centralServerId(
    targetServerId ?? input.playerView.run?.attackedServerId,
  );
  const installedInterfaceTargets = new Set(
    (input.playerView.own.rig ?? [])
      .filter((card) =>
        isCentralPressureCardForMetrics(card.definitionId, true),
      )
      .flatMap((card) => centralPressureTargetsForCard(card.definitionId)),
  );
  const hasAnyInstalledInterface = installedInterfaceTargets.size > 0;
  const sourceDefinitionId = sourceDefinitionIdForSimulationAction(
    input,
    action,
  );
  const eventTargets =
    action.type === "play_event"
      ? centralPressureTargetsForCard(sourceDefinitionId)
      : [];
  const eventGoodTarget = eventTargets.some((target) =>
    centralPressureTargetIsGoodForMetrics(input, target),
  );
  const interfaceInstallOpportunity = input.legalActions.some((candidate) => {
    if (candidate.type !== "install_card") return false;
    const definitionId = sourceDefinitionIdForSimulationAction(
      input,
      candidate,
    );
    return isCentralPressureCardForMetrics(definitionId, true);
  });
  const interfaceInstallTaken =
    action.type === "install_card" &&
    isCentralPressureCardForMetrics(sourceDefinitionId, true);
  const closeoutOpportunityRaw =
    input.playerView.agendaPointsToWin - input.playerView.own.agendaPoints <=
      2 &&
    (centralTarget !== undefined ||
      (["hq", "rd"] as const).some((target) =>
        centralPressureTargetIsGoodForMetrics(input, target),
      ));
  const trueCloseout = centralTarget
    ? trueCentralCloseoutProfileForMetrics(input, centralTarget)
    : bestTrueCentralCloseoutProfileForMetrics(input);
  const centralRun = action.type === "start_run" && centralTarget !== undefined;
  const matchingInterface =
    centralTarget !== undefined && installedInterfaceTargets.has(centralTarget);
  const anyMultiaccessInstalled = (input.playerView.own.rig ?? []).some(
    (card) =>
      rolesForCardId(card.definitionId).some((role) =>
        role.includes("multiaccess"),
      ),
  );
  const repeatedLowValue =
    centralTarget !== undefined &&
    centralRun &&
    isRepeatedLowValueCentralRunForMetrics(input, centralTarget) &&
    !centralRepeatHasFreshValueForMetrics(input, centralTarget, {
      matchingInterface,
      anyMultiaccessInstalled,
      eventGoodTarget,
      trueCloseout: trueCloseout.opportunity,
    });
  const repeatWindow =
    centralTarget !== undefined &&
    centralRun &&
    centralRunStreakWithoutValueForMetrics(input, centralTarget) > 0;
  const repeatWithFreshValue =
    centralTarget !== undefined &&
    centralRun &&
    repeatWindow &&
    centralRepeatHasFreshValueForMetrics(input, centralTarget, {
      matchingInterface,
      anyMultiaccessInstalled,
      eventGoodTarget,
      trueCloseout: trueCloseout.opportunity,
    });
  const noFresh = runnerNoFreshCentralContextForMetrics(input);
  const noFreshRunTaken =
    centralRun &&
    centralTarget !== undefined &&
    noFresh.targets.includes(centralTarget);
  const substitutionType =
    noFresh.targets.length > 0 && !noFreshRunTaken
      ? noFreshCentralSubstitutionTypeForAction(input, action)
      : undefined;
  const streakWithoutValue =
    centralTarget !== undefined && centralRun
      ? centralRunStreakWithoutValueForMetrics(input, centralTarget)
      : 0;
  const reserveTarget = runnerCreditReserveTargetForInput(input);
  const server = centralTarget
    ? input.playerView.servers.find(
        (candidate) => candidate.id === centralTarget,
      )
    : undefined;
  const visibleBreakCost =
    centralTarget && server
      ? (assessKnownRezzedIcePath(
          server.ice,
          input.playerView.own.rig ?? [],
          input.playerView.own.credits,
          server.root,
        ).visibleBreakCost ?? 0)
      : 0;
  const insufficientReserve =
    centralRun &&
    input.playerView.own.credits - visibleBreakCost < reserveTarget;
  const hqMemoryDiagnostics = runnerHqMemoryDiagnosticsForMetrics(
    input,
    centralRun,
    centralTarget,
  );
  const knownCardPositionDiagnostics =
    runnerKnownCardPositionDiagnosticsForMetrics(input, action, targetServerId);
  return {
    ...hqMemoryDiagnostics,
    ...knownCardPositionDiagnostics,
    ...(centralRun && (matchingInterface || anyMultiaccessInstalled)
      ? { runnerCentralRunWithMultiaccess: true }
      : {}),
    ...(centralRun && hasAnyInstalledInterface
      ? { runnerCentralRunWithInterfaceInstalled: true }
      : {}),
    ...(centralRun &&
    centralTarget === "hq" &&
    installedInterfaceTargets.has("hq")
      ? { runnerHqRunWithHqInterface: true }
      : {}),
    ...(centralRun &&
    centralTarget === "rd" &&
    installedInterfaceTargets.has("rd")
      ? { runnerRndRunWithRndInterface: true }
      : {}),
    ...(action.type === "play_event" && eventTargets.length > 0
      ? { runnerCentralRunEventPlayed: true }
      : {}),
    ...(action.type === "play_event" && eventGoodTarget
      ? { runnerCentralRunEventWithGoodTarget: true }
      : {}),
    ...(repeatedLowValue ? { runnerRepeatedLowValueCentralRun: true } : {}),
    ...(repeatWindow ? { runnerCentralRunRepeatWindow: true } : {}),
    ...(repeatWithFreshValue
      ? { runnerRepeatedCentralRunWithFreshValue: true }
      : {}),
    ...(repeatWindow && !repeatWithFreshValue
      ? { runnerRepeatedCentralRunWithoutFreshValue: true }
      : {}),
    ...(repeatedLowValue ? { runnerCentralRunStalePenaltyApplied: true } : {}),
    ...(streakWithoutValue > 0
      ? { runnerCentralRunStreakWithoutValue: streakWithoutValue }
      : {}),
    ...(insufficientReserve
      ? { runnerCentralRunStartedWithInsufficientPostRunReserve: true }
      : {}),
    ...(closeoutOpportunityRaw
      ? { runnerCentralCloseoutOpportunityRaw: true }
      : {}),
    ...(trueCloseout.opportunity
      ? {
          runnerTrueCentralCloseoutOpportunity: true,
          runnerCentralCloseoutOpportunity: true,
          runnerCentralCloseoutReason: trueCloseout.reasons[0],
        }
      : {}),
    ...(closeoutOpportunityRaw && !trueCloseout.opportunity && !centralRun
      ? { runnerCentralCloseoutSkippedWithGoodReason: true }
      : {}),
    ...(closeoutOpportunityRaw && trueCloseout.opportunity && !centralRun
      ? { runnerCentralCloseoutSkippedWithoutReason: true }
      : {}),
    ...(centralRun && trueCloseout.opportunity
      ? { runnerCentralCloseoutRunTaken: true }
      : {}),
    ...(action.type === "steal_agenda" &&
    centralTarget &&
    trueCloseout.opportunity
      ? { runnerCentralCloseoutSuccess: true }
      : {}),
    ...(input.playerView.activeSide === "runner" &&
    input.playerView.phase === "runner_action_phase" &&
    !centralRun &&
    closeoutOpportunityRaw &&
    !trueCloseout.opportunity
      ? { runnerCentralPressureNoopDecision: true }
      : {}),
    ...(noFresh.targets.length > 0
      ? { runnerNoFreshCentralServerIds: noFresh.targets }
      : {}),
    ...(noFresh.betterAlternatives.length > 0
      ? {
          runnerNoFreshCentralBetterAlternativeTypes:
            noFresh.betterAlternatives,
        }
      : {}),
    ...(noFreshRunTaken ? { runnerNoFreshCentralRunTaken: true } : {}),
    ...(substitutionType
      ? { runnerNoFreshCentralSubstitutionType: substitutionType }
      : {}),
    ...(noFreshRunTaken && noFresh.allowedReasons[0]
      ? { runnerStaleCentralAllowedReason: noFresh.allowedReasons[0] }
      : {}),
    ...(interfaceInstallOpportunity
      ? { runnerInterfaceInstallOpportunity: true }
      : {}),
    ...(interfaceInstallTaken ? { runnerInterfaceInstallTaken: true } : {}),
    ...(hasAnyInstalledInterface &&
    input.playerView.activeSide === "runner" &&
    input.playerView.phase === "runner_action_phase" &&
    !centralRun &&
    action.type === "end_turn"
      ? { runnerInterfaceInstalledButUnusedTurn: true }
      : {}),
  };
}

function runnerHqMemoryDiagnosticsForMetrics(
  input: AiDecisionInput,
  centralRun: boolean,
  centralTarget: "hq" | "rd" | "archives" | undefined,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  const memory =
    reconstructBeliefState(input).runnerOpponentModel?.hqHandMemory;
  if (!memory) return {};
  const knownAgendaDefinitions = memory.knownDefinitions.filter(
    (definitionId) => definitionTypeForMetrics(definitionId) === "agenda",
  );
  const knownAgendaPoints = knownAgendaDefinitions.reduce(
    (sum, definitionId) => sum + agendaPointsForMetrics(definitionId),
    0,
  );
  const knownNonAgendaCount =
    memory.knownDefinitions.length - knownAgendaDefinitions.length;
  const unknownCount = Math.max(0, memory.handCount - memory.knownCount);
  const knownFraction =
    memory.handCount > 0 ? round(memory.knownCount / memory.handCount) : 0;
  const fullyKnownNoAgenda =
    memory.allCardsKnown &&
    memory.knownCount > 0 &&
    knownAgendaDefinitions.length === 0 &&
    memory.knownDefinitions.every((definitionId) =>
      isLowValueKnownAccessCard(definitionId, input.playerView.own.credits),
    );
  const knownCardValue =
    centralRun && centralTarget === "hq"
      ? knownAgendaDefinitions.length * 520 + knownAgendaPoints * 80
      : 0;
  const unknownCardValue =
    centralRun && centralTarget === "hq" ? Math.min(140, unknownCount * 55) : 0;
  const invalidationText = memory.invalidationReasons.join("|");
  return {
    hqKnownCards: memory.knownCount,
    hqUnknownCards: unknownCount,
    hqKnownFraction: knownFraction,
    ...(memory.allCardsKnown ? { hqFullyKnown: true } : {}),
    hqKnownAgendaCount: knownAgendaDefinitions.length,
    hqKnownNonAgendaCount: knownNonAgendaCount,
    hqKnownAgendaPoints: knownAgendaPoints,
    ...(invalidationText.includes("corp_draw_added_unknown_hq_card")
      ? { hqMemoryInvalidatedByDraw: true }
      : {}),
    ...(invalidationText.includes("known_hq_card_installed") ||
    invalidationText.includes("corp_installed_hidden_hq_card")
      ? { hqMemoryInvalidatedByInstall: true }
      : {}),
    ...(invalidationText.includes("known_hq_card_played") ||
    invalidationText.includes("corp_played_unknown_hq_card")
      ? { hqMemoryInvalidatedByPlay: true }
      : {}),
    ...(invalidationText.includes("corp_discarded_hq_card")
      ? { hqMemoryInvalidatedByDiscard: true }
      : {}),
    ...(invalidationText.includes("shuffle_changed_hq_hand") ||
    invalidationText.includes("arrange_changed_hq_hand") ||
    invalidationText.includes("swap_changed_hq_hand")
      ? { hqMemoryInvalidatedByShuffleOrReorder: true }
      : {}),
    ...(knownCardValue > 0 ? { hqRunValueFromKnownCards: knownCardValue } : {}),
    ...(unknownCardValue > 0
      ? { hqRunValueFromUnknownCards: unknownCardValue }
      : {}),
    ...(centralRun && centralTarget === "hq" && fullyKnownNoAgenda
      ? { hqRunSuppressedBecauseFullyKnownNoAgenda: true }
      : {}),
    ...(centralRun &&
    centralTarget === "hq" &&
    knownAgendaDefinitions.length > 0
      ? { hqRunBoostedBecauseKnownAgenda: true }
      : {}),
    ...(centralRun && centralTarget === "hq" && unknownCount > 0
      ? { hqRunBoostedBecauseUnknownCardsRemain: true }
      : {}),
    ...(centralRun &&
    centralTarget === "hq" &&
    isRepeatedLowValueCentralRunForMetrics(input, "hq") &&
    !input.eventTail.some(eventMayChangeHqPressureForMetrics)
      ? { hqRunRepeatedWithoutNewHqInfo: true }
      : {}),
  };
}

function runnerKnownCardPositionDiagnosticsForMetrics(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "runner" || action.side !== "runner") return {};
  const belief = reconstructBeliefState(input);
  const memory = belief.runnerOpponentModel?.knownPositionMemory ?? [];
  const hqMemory = belief.runnerOpponentModel?.hqHandMemory;
  const invalidationText = [
    ...(belief.runnerOpponentModel?.rndTopFreshness.invalidationReasons ?? []),
    ...(hqMemory?.invalidationReasons ?? []),
  ].join("|");
  const knownRemote = memory.filter(
    (entry) =>
      entry.zone.startsWith("remote_") && entry.positionKey.startsWith("root:"),
  );
  const knownRemoteAgendas = knownRemote.filter(
    (entry) => definitionTypeForMetrics(entry.definitionId) === "agenda",
  );
  const knownRemoteTrashable = knownRemote.filter((entry) => {
    const type = definitionTypeForMetrics(entry.definitionId);
    return (
      (type === "asset" || type === "upgrade") &&
      trashCostForDefinitionForMetrics(entry.definitionId) !== undefined
    );
  });
  const knownUnrezzedIce = memory.filter((entry) =>
    entry.positionKey.startsWith("ice:"),
  );
  const runTarget =
    action.type === "start_run"
      ? (targetServerId ??
        (typeof action.payload?.serverId === "string"
          ? action.payload.serverId
          : undefined))
      : undefined;
  const targetKnownRemote = runTarget
    ? knownRemote.filter((entry) => entry.zone === runTarget)
    : [];
  const targetKnownUnrezzedIce = runTarget
    ? knownUnrezzedIce.filter((entry) => entry.zone === runTarget)
    : [];
  const runCostAdjusted = targetKnownUnrezzedIce.reduce(
    (sum, entry) =>
      sum + visibleBreakCostForKnownIceDefinition(input, entry.definitionId),
    0,
  );
  const hqKnownFromRndDraw =
    hqMemory?.invalidationReasons.some((reason) =>
      reason.includes("known_rnd_top_moved_to_hq"),
    ) ?? false;
  const hqKnownAgendaFromRnd =
    hqKnownFromRndDraw &&
    (hqMemory?.knownDefinitions ?? []).some(
      (definitionId) => definitionTypeForMetrics(definitionId) === "agenda",
    );
  const rndFreshness = belief.runnerOpponentModel?.rndTopFreshness;
  const rndTopRemoved = rndFreshness?.freshness === "fresh_after_top_removed";
  const rndKnownTopAgenda =
    rndFreshness?.knownTopDefinitionId !== undefined &&
    definitionTypeForMetrics(rndFreshness.knownTopDefinitionId) === "agenda";
  const rndKnownTopNonAgenda =
    rndFreshness?.knownTopDefinitionId !== undefined && !rndKnownTopAgenda;
  const rndStaleKnownTop = rndFreshness?.freshness === "stale_known_same_top";
  const isRndRun = action.type === "start_run" && runTarget === "rd";
  const rndFreshOpportunity =
    rndTopRemoved ||
    rndKnownTopAgenda ||
    rndFreshness?.freshenedByRunnerAccess === true;
  return {
    ...(memory.some(
      (entry) => entry.zone === "rd" && entry.positionKey === "top",
    )
      ? { knownRndTopCard: true }
      : {}),
    ...(invalidationText.includes("known_rnd_top_moved_to_hq")
      ? { knownRndTopMovedToHq: true, hqKnownFromRndDraw: true }
      : {}),
    ...(invalidationText.includes("corp_draw_from_rd") ||
    invalidationText.includes("shuffle_changed_rd_top") ||
    invalidationText.includes("arrange_changed_rd_top") ||
    invalidationText.includes("swap_changed_rd_top")
      ? { knownRndTopInvalidated: true }
      : {}),
    ...(action.type === "start_run" &&
    runTarget === "hq" &&
    hqKnownAgendaFromRnd
      ? { hqRunBoostedByRndToHqAgenda: true }
      : {}),
    ...(action.type === "start_run" &&
    runTarget === "hq" &&
    hqKnownFromRndDraw &&
    !hqKnownAgendaFromRnd
      ? { hqRunSuppressedByRndToHqNonAgenda: true }
      : {}),
    ...([
      "steal_agenda",
      "trash_accessed_card",
      "move_to_removed_from_game",
      "move_to_set_aside",
    ].includes(action.type) && targetServerId === "rd"
      ? { rndAccessRemovedTopCard: true }
      : {}),
    ...(action.type === "steal_agenda" && targetServerId === "rd"
      ? { rndAccessStoleAgenda: true }
      : {}),
    ...(action.type === "trash_accessed_card" && targetServerId === "rd"
      ? { rndAccessTrashedCard: true }
      : {}),
    ...(action.type === "access_card" &&
    targetServerId === "rd" &&
    !input.legalActions.some(
      (candidate) =>
        candidate.type === "steal_agenda" ||
        candidate.type === "trash_accessed_card",
    )
      ? { rndAccessLeftTopCardUnchanged: true }
      : {}),
    ...(rndFreshness?.freshenedByRunnerAccess === true
      ? { rndTopFreshenedByRunnerAccess: true }
      : {}),
    ...(rndFreshness?.invalidationReasons.some((reason) =>
      reason.includes("rd_known_top_sequence_advanced"),
    )
      ? {
          rndKnownTopAdvancedAfterAccess: true,
          rndKnownTopSequenceAdvanced: true,
        }
      : {}),
    ...(isRndRun && rndTopRemoved ? { rndRepeatRunAfterTopRemoved: true } : {}),
    ...(isRndRun && rndStaleKnownTop
      ? { rndRepeatRunAfterTopUnchanged: true }
      : {}),
    ...(isRndRun && rndTopRemoved
      ? { rndRepeatRunBoostedByFreshTop: true }
      : {}),
    ...(isRndRun && rndStaleKnownTop
      ? { rndRepeatRunSuppressedBecauseKnownStaleTop: true }
      : {}),
    ...(isRndRun && rndKnownTopAgenda
      ? { rndRepeatRunBoostedByKnownAgendaTop: true }
      : {}),
    ...(isRndRun && rndStaleKnownTop && rndKnownTopNonAgenda
      ? { rndRepeatRunSuppressedBecauseKnownNonAgendaTop: true }
      : {}),
    ...(rndFreshOpportunity ? { rndFreshTopPressureOpportunity: true } : {}),
    ...(isRndRun && rndFreshOpportunity
      ? { rndFreshTopPressureTaken: true }
      : {}),
    ...(rndFreshOpportunity && !isRndRun
      ? { rndFreshTopPressureSkipped: true }
      : {}),
    ...(isRndRun && rndStaleKnownTop && rndKnownTopNonAgenda
      ? {
          rndStaleTopRepeatMistake: true,
          rndAccessNoValueRepeatStale: true,
        }
      : {}),
    ...(rndTopRemoved &&
    input.playerView.agendaPointsToWin - input.playerView.own.agendaPoints <= 2
      ? { rndCloseoutOpportunityAfterTopRemoved: true }
      : {}),
    ...(knownRemote.length > 0 ? { knownRemoteCards: knownRemote.length } : {}),
    ...(knownRemoteAgendas.length > 0
      ? { knownRemoteAgendas: knownRemoteAgendas.length }
      : {}),
    ...(knownRemoteTrashable.length > 0
      ? { knownRemoteTrashableCards: knownRemoteTrashable.length }
      : {}),
    ...(knownRemote.length > 0
      ? { remoteMemoryRetainedAfterAccess: true }
      : {}),
    ...(invalidationText.includes("remote_state_changed") ||
    memory.some((entry) =>
      entry.invalidatedBy.some(
        (reason) => reason.includes("install") || reason.includes("move"),
      ),
    )
      ? { remoteMemoryInvalidatedByInstallOrMove: true }
      : {}),
    ...(action.type === "start_run" &&
    targetKnownRemote.some(
      (entry) => definitionTypeForMetrics(entry.definitionId) === "agenda",
    )
      ? { remoteRunBoostedByKnownRemoteAgenda: true }
      : {}),
    ...(action.type === "start_run" &&
    targetKnownRemote.some((entry) =>
      isLowValueKnownAccessCard(
        entry.definitionId,
        input.playerView.own.credits,
      ),
    )
      ? { remoteRunSuppressedByKnownLowValueRemote: true }
      : {}),
    ...(action.type === "start_run" &&
    targetKnownRemote.some((entry) => {
      const type = definitionTypeForMetrics(entry.definitionId);
      return (
        (type === "asset" || type === "upgrade") &&
        trashCostForDefinitionForMetrics(entry.definitionId) !== undefined
      );
    })
      ? { remoteTrashBoostedByKnownRemoteTrashable: true }
      : {}),
    ...(knownUnrezzedIce.length > 0
      ? {
          knownUnrezzedIceFromExpose: knownUnrezzedIce.length,
          knownUnrezzedIceRetained: true,
        }
      : {}),
    ...(invalidationText.includes("conceal") ||
    invalidationText.includes("reorder")
      ? { knownUnrezzedIceInvalidated: true }
      : {}),
    ...(runCostAdjusted > 0
      ? { runCostAdjustedByKnownUnrezzedIce: runCostAdjusted }
      : {}),
    ...(action.type === "jack_out" && knownUnrezzedIce.length > 0
      ? { jackOutInfluencedByKnownUnrezzedIce: true }
      : {}),
    ...(action.type === "install_card" && knownUnrezzedIce.length > 0
      ? { rigPlanInfluencedByKnownUnrezzedIce: true }
      : {}),
  };
}

function definitionTypeForMetrics(definitionId: string): string | undefined {
  return (
    DEMO_CARDS_BY_ID[definitionId]?.type ?? RUNTIME_CARDS[definitionId]?.type
  );
}

function agendaPointsForMetrics(definitionId: string): number {
  return (
    RUNTIME_CARDS[definitionId]?.numeric.agendaPoints ??
    DEMO_CARDS_BY_ID[definitionId]?.agendaPoints ??
    0
  );
}

function trashCostForDefinitionForMetrics(
  definitionId: string,
): number | undefined {
  return (
    RUNTIME_CARDS[definitionId]?.numeric.trashCost ??
    DEMO_CARDS_BY_ID[definitionId]?.trashCost
  );
}

function remoteRootTrashCostForMetrics(card: VisibleCard): number | undefined {
  if (!card.definitionId) return undefined;
  return trashCostForDefinitionForMetrics(card.definitionId);
}

function visibleBreakCostForKnownIceDefinition(
  input: AiDecisionInput,
  definitionId: string,
): number {
  const definition = DEMO_CARDS_BY_ID[definitionId];
  if (!definition) return 0;
  const assessment = assessKnownRezzedIcePath(
    [
      {
        instanceId: `known_unrezzed_${definitionId}`,
        known: true,
        definitionId,
        type: "ice",
        subtypes: definition.subtypes ?? [],
        rezzed: true,
        strength: definition.strength,
        subroutines: definition.subroutines ?? [],
        owner: "corp",
        controller: "corp",
      } as VisibleCard,
    ],
    input.playerView.own.rig ?? [],
    input.playerView.own.credits,
  );
  return assessment.visibleBreakCost ?? 0;
}

function eventMayChangeHqPressureForMetrics(event: PublicGameEvent): boolean {
  const actionType =
    typeof event.publicPayload.actionType === "string"
      ? event.publicPayload.actionType
      : event.type;
  return (
    actionType === "draw_card" ||
    actionType === "mandatory_draw" ||
    actionType === "install_card" ||
    actionType === "play_operation" ||
    actionType === "discard_card" ||
    actionType === "resolve_choice"
  );
}

function centralServerId(
  serverId: string | undefined,
): "hq" | "rd" | "archives" | undefined {
  return serverId === "hq" || serverId === "rd" || serverId === "archives"
    ? serverId
    : undefined;
}

function isCentralPressureCardForMetrics(
  definitionId: string | undefined,
  installedOnly: boolean,
): boolean {
  if (!definitionId) return false;
  const roles = rolesForCardId(definitionId);
  if (!roles.some(isRunnerPressureRole)) return false;
  if (!installedOnly) return true;
  const type =
    DEMO_CARDS_BY_ID[definitionId]?.type ?? RUNTIME_CARDS[definitionId]?.type;
  return type === "hardware" || type === "program" || type === "resource";
}

function centralPressureTargetsForCard(
  definitionId: string | undefined,
): Array<"hq" | "rd" | "archives"> {
  if (!definitionId) return [];
  const roles = rolesForCardId(definitionId);
  const targets: Array<"hq" | "rd" | "archives"> = [];
  if (
    definitionId === "onr_v1_139_r-and-d-interface" ||
    roles.includes("pressure_rnd") ||
    roles.includes("rnd_pressure")
  )
    targets.push("rd");
  if (
    definitionId === "onr_v1_129_hq-interface" ||
    roles.includes("pressure_hq") ||
    roles.includes("hq_pressure")
  )
    targets.push("hq");
  if (roles.includes("archives_pressure")) targets.push("archives");
  if (
    targets.length === 0 &&
    roles.some((role) => role.includes("multiaccess")) &&
    [
      "onr_v1_024_expert-schedule-analyzer",
      "onr_v1_041_microtech-ai-interface",
      "onr_v1_105_priority-wreck",
    ].includes(definitionId)
  )
    targets.push("rd", "hq");
  return sortedUnique(targets) as Array<"hq" | "rd" | "archives">;
}

function centralPressureTargetIsGoodForMetrics(
  input: AiDecisionInput,
  target: "hq" | "rd" | "archives",
): boolean {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === target,
  );
  if (!server) return false;
  const assessment = assessKnownRezzedIcePath(
    server.ice,
    input.playerView.own.rig ?? [],
    input.playerView.own.credits,
    server.root,
  );
  if (assessment.blocked) return false;
  const cheap =
    (assessment.visibleBreakCost ?? 0) <= 1 || server.ice.length === 0;
  if (!cheap) return false;
  if (target === "archives")
    return server.root.some((card) => card.known && card.type === "agenda");
  if (
    input.playerView.agendaPointsToWin - input.playerView.own.agendaPoints <=
    2
  )
    return true;
  if (target === "hq") return input.playerView.opponent.handCount >= 3;
  return true;
}

function bestTrueCentralCloseoutProfileForMetrics(input: AiDecisionInput): {
  opportunity: boolean;
  reasons: string[];
  target?: "hq" | "rd" | "archives";
} {
  const profiles = (["rd", "hq", "archives"] as const)
    .map((target) => ({
      target,
      ...trueCentralCloseoutProfileForMetrics(input, target),
    }))
    .filter((profile) => profile.opportunity)
    .sort(
      (left, right) =>
        right.reasons.length - left.reasons.length ||
        left.target.localeCompare(right.target),
    );
  return profiles[0] ?? { opportunity: false, reasons: [] };
}

function trueCentralCloseoutProfileForMetrics(
  input: AiDecisionInput,
  target: "hq" | "rd" | "archives",
): { opportunity: boolean; reasons: string[] } {
  const pointsNeeded =
    input.playerView.agendaPointsToWin - input.playerView.own.agendaPoints;
  if (pointsNeeded > 2) return { opportunity: false, reasons: [] };
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === target,
  );
  if (!server) return { opportunity: false, reasons: [] };
  const assessment = assessKnownRezzedIcePath(
    server.ice,
    input.playerView.own.rig ?? [],
    input.playerView.own.credits,
    server.root,
  );
  if (assessment.blocked) return { opportunity: false, reasons: [] };
  const visibleBreakCost = assessment.visibleBreakCost ?? 0;
  const openOrCheap = visibleBreakCost <= 1 || server.ice.length === 0;
  if (!openOrCheap) return { opportunity: false, reasons: [] };
  if (target === "archives") {
    const visibleAgenda = server.root.some(
      (card) => card.known && card.type === "agenda",
    );
    return {
      opportunity: visibleAgenda,
      reasons: visibleAgenda ? ["archives_visible_agenda"] : [],
    };
  }
  const installedTargets = new Set(
    (input.playerView.own.rig ?? [])
      .filter((card) =>
        isCentralPressureCardForMetrics(card.definitionId, true),
      )
      .flatMap((card) => centralPressureTargetsForCard(card.definitionId)),
  );
  const matchingInterface = installedTargets.has(target);
  const anyMultiaccess = (input.playerView.own.rig ?? []).some((card) =>
    rolesForCardId(card.definitionId).some((role) =>
      role.includes("multiaccess"),
    ),
  );
  const hasRunEvent = input.legalActions.some((action) => {
    if (action.side !== "runner" || action.type !== "play_event") return false;
    return centralPressureTargetsForCard(
      sourceDefinitionIdForSimulationAction(input, action),
    ).includes(target);
  });
  const hqPressure =
    target === "hq" && input.playerView.opponent.handCount >= 5;
  const rndFreshness = false;
  const reasons = [
    "near_win",
    ...(matchingInterface ? ["interface"] : []),
    ...(anyMultiaccess ? ["multiaccess"] : []),
    ...(hasRunEvent ? ["run_event"] : []),
    ...(hqPressure ? ["hq_pressure"] : []),
    ...(rndFreshness ? ["rnd_freshness"] : []),
  ];
  const hasSpecificPressure =
    matchingInterface ||
    anyMultiaccess ||
    hasRunEvent ||
    hqPressure ||
    rndFreshness;
  return {
    opportunity: hasSpecificPressure,
    reasons,
  };
}

function isRepeatedLowValueCentralRunForMetrics(
  input: AiDecisionInput,
  target: "hq" | "rd" | "archives",
): boolean {
  return centralRunStreakWithoutValueForMetrics(input, target) > 0;
}

function centralRepeatHasFreshValueForMetrics(
  input: AiDecisionInput,
  target: "hq" | "rd" | "archives",
  context: {
    matchingInterface: boolean;
    anyMultiaccessInstalled: boolean;
    eventGoodTarget: boolean;
    trueCloseout: boolean;
  },
): boolean {
  if (
    context.matchingInterface ||
    context.anyMultiaccessInstalled ||
    context.eventGoodTarget ||
    context.trueCloseout
  )
    return true;
  return !recentCentralRunSameTargetWithoutRefresh(input, target);
}

function runnerNoFreshCentralContextForMetrics(input: AiDecisionInput): {
  targets: Array<"hq" | "rd" | "archives">;
  betterAlternatives: string[];
  allowedReasons: string[];
} {
  const targets = (["rd", "hq", "archives"] as const).filter((target) => {
    const hasRun = input.legalActions.some(
      (action) =>
        action.type === "start_run" && action.payload?.serverId === target,
    );
    if (!hasRun) return false;
    const closeout = trueCentralCloseoutProfileForMetrics(
      input,
      target,
    ).opportunity;
    const server = input.playerView.servers.find(
      (candidate) => candidate.id === target,
    );
    const matchingInterface = (input.playerView.own.rig ?? []).some((card) =>
      centralPressureTargetsForCard(card.definitionId).includes(target),
    );
    const anyMultiaccess = (input.playerView.own.rig ?? []).some((card) =>
      rolesForCardId(card.definitionId).some((role) =>
        role.includes("multiaccess"),
      ),
    );
    return (
      centralRunStreakWithoutValueForMetrics(input, target) > 0 &&
      !matchingInterface &&
      !anyMultiaccess &&
      !closeout &&
      !centralRunEventGoodForTarget(input, target) &&
      server !== undefined
    );
  });
  if (targets.length === 0)
    return { targets: [], betterAlternatives: [], allowedReasons: [] };

  const better = new Set<string>();
  const reserveTarget = runnerCreditReserveTargetForInput(input);
  if (
    input.playerView.own.credits <= reserveTarget &&
    input.legalActions.some((action) => isRunnerEconomyAction(input, action))
  )
    better.add("economy");
  if (
    input.legalActions.some(
      (action) =>
        action.type === "start_run" &&
        typeof action.payload?.serverId === "string" &&
        isRemoteServerTarget(action.payload.serverId) &&
        runnerRemoteThreatProfile(input, action.payload.serverId).contestable,
    )
  )
    better.add("remote_contest");
  if (
    input.legalActions.some(
      (action) =>
        action.type === "install_card" &&
        rolesForAction(input, action).some((role) =>
          role.startsWith("breaker_"),
        ),
    )
  )
    better.add("rig_unlock");
  if (
    input.legalActions.some((action) => {
      if (action.type !== "install_card") return false;
      const definitionId = sourceDefinitionIdForSimulationAction(input, action);
      return isCentralPressureCardForMetrics(definitionId, true);
    })
  )
    better.add("pressure_install");
  if (
    input.legalActions.some((action) => {
      if (
        action.type === "draw_card" &&
        input.playerView.own.gripOrHq.length <= 2
      )
        return true;
      if (action.type !== "play_event" && action.type !== "resolve_choice")
        return false;
      return rolesForAction(input, action).some(
        (role) =>
          role === "draw" ||
          role === "setup" ||
          role.includes("search") ||
          role.includes("tutor"),
      );
    })
  )
    better.add("setup_search");

  const allowed = new Set<string>();
  for (const target of targets) {
    const profile = trueCentralCloseoutProfileForMetrics(input, target);
    if (profile.opportunity) allowed.add("closeout");
    const installed = input.playerView.own.rig ?? [];
    if (
      installed.some((card) =>
        centralPressureTargetsForCard(card.definitionId).includes(target),
      )
    )
      allowed.add("interface");
    if (
      installed.some((card) =>
        rolesForCardId(card.definitionId).some((role) =>
          role.includes("multiaccess"),
        ),
      )
    )
      allowed.add("multiaccess");
    const server = input.playerView.servers.find(
      (candidate) => candidate.id === target,
    );
    const assessment = assessKnownRezzedIcePath(
      server?.ice ?? [],
      input.playerView.own.rig ?? [],
      input.playerView.own.credits,
      server?.root ?? [],
    );
    if (
      !assessment.blocked &&
      ((assessment.visibleBreakCost ?? 0) <= 0 ||
        (server?.ice.length ?? 0) === 0)
    )
      allowed.add("central_open");
  }
  const remoteContestable = input.legalActions.some(
    (action) =>
      action.type === "start_run" &&
      typeof action.payload?.serverId === "string" &&
      isRemoteServerTarget(action.payload.serverId) &&
      runnerRemoteThreatProfile(input, action.payload.serverId).contestable,
  );
  if (!remoteContestable) allowed.add("remote_uncontestable");
  if (better.size === 0) allowed.add("no_better_action");
  return {
    targets,
    betterAlternatives: [...better].sort(),
    allowedReasons: [...allowed].sort(),
  };
}

function centralRunEventGoodForTarget(
  input: AiDecisionInput,
  target: "hq" | "rd" | "archives",
): boolean {
  return input.legalActions.some((action) => {
    if (action.side !== "runner" || action.type !== "play_event") return false;
    return centralPressureTargetsForCard(
      sourceDefinitionIdForSimulationAction(input, action),
    ).includes(target);
  });
}

function noFreshCentralSubstitutionTypeForAction(
  input: AiDecisionInput,
  action: LegalAction,
):
  | "economy"
  | "rig_unlock"
  | "remote_contest"
  | "pressure_install"
  | "setup_search"
  | "end_turn"
  | undefined {
  if (isRunnerEconomyAction(input, action)) return "economy";
  if (
    action.type === "start_run" &&
    typeof action.payload?.serverId === "string" &&
    isRemoteServerTarget(action.payload.serverId)
  )
    return "remote_contest";
  if (action.type === "install_card") {
    const definitionId = sourceDefinitionIdForSimulationAction(input, action);
    if (isCentralPressureCardForMetrics(definitionId, true))
      return "pressure_install";
    if (
      rolesForAction(input, action).some((role) => role.startsWith("breaker_"))
    )
      return "rig_unlock";
  }
  if (
    action.type === "draw_card" ||
    (action.type === "play_event" &&
      rolesForAction(input, action).some(
        (role) =>
          role === "draw" || role === "setup" || role.includes("search"),
      )) ||
    action.type === "resolve_choice"
  )
    return "setup_search";
  if (action.type === "end_turn") return "end_turn";
  return undefined;
}

function recentCentralRunSameTargetWithoutRefresh(
  input: AiDecisionInput,
  target: "hq" | "rd" | "archives",
): boolean {
  const history = [...input.playerView.publicEvents, ...input.eventTail].sort(
    (left, right) =>
      (left.stateVersionAfter ?? 0) - (right.stateVersionAfter ?? 0),
  );
  let lastSameRun = -1;
  for (let index = history.length - 1; index >= 0; index -= 1) {
    const event = history[index]!;
    if (
      aiServerIdFromEvent(event) === target &&
      (event.publicPayload.actionType === "start_run" ||
        event.type === "run_started")
    ) {
      lastSameRun = index;
      break;
    }
  }
  if (lastSameRun < 0) return false;
  const last = history[lastSameRun];
  if (
    !last ||
    input.playerView.stateVersion - (last.stateVersionAfter ?? 0) > 8
  )
    return false;
  const after = history.slice(lastSameRun + 1);
  return !after.some((event) => centralRefreshEventForTarget(event, target));
}

function centralRefreshEventForTarget(
  event: PublicGameEvent,
  target: "hq" | "rd" | "archives",
): boolean {
  const actionType =
    typeof event.publicPayload.actionType === "string"
      ? event.publicPayload.actionType
      : event.type;
  if (actionType === "steal_agenda" || actionType === "trash_accessed_card")
    return true;
  if (target === "hq")
    return (
      actionType === "draw_card" ||
      actionType === "mandatory_draw" ||
      actionType === "install_card" ||
      actionType === "play_operation"
    );
  if (target === "rd")
    return (
      actionType === "draw_card" ||
      actionType === "mandatory_draw" ||
      actionType === "shuffle_stack" ||
      actionType === "reorder_cards"
    );
  return actionType === "trash_card";
}

function centralRunStreakWithoutValueForMetrics(
  input: AiDecisionInput,
  target: "hq" | "rd" | "archives",
): number {
  const history = [...input.playerView.publicEvents, ...input.eventTail].sort(
    (left, right) =>
      (left.stateVersionAfter ?? 0) - (right.stateVersionAfter ?? 0),
  );
  let streak = 0;
  for (let index = history.length - 1; index >= 0; index -= 1) {
    const event = history[index]!;
    const actionType =
      typeof event.publicPayload.actionType === "string"
        ? event.publicPayload.actionType
        : event.type;
    if (
      actionType === "steal_agenda" ||
      actionType === "trash_accessed_card" ||
      actionType === "score_agenda"
    )
      break;
    if (aiServerIdFromEvent(event) === target && actionType === "start_run") {
      streak += 1;
      continue;
    }
    if (
      (target === "hq" &&
        (actionType === "draw_card" || actionType === "mandatory_draw")) ||
      (target === "rd" &&
        (actionType === "draw_card" ||
          actionType === "mandatory_draw" ||
          actionType === "shuffle_stack")) ||
      actionType === "install_card"
    )
      break;
  }
  return streak;
}

function runnerReserveDiagnosticsForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
  stateAfterAction: GameState,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "runner" || action.side !== "runner") return {};
  const creditsBefore = input.playerView.own.credits;
  const creditsAfter = stateAfterAction.runner.credits;
  const creditDelta = creditsAfter - creditsBefore;
  const reserveTarget = runnerCreditReserveTargetForInput(input);
  const belowBefore = creditsBefore < reserveTarget;
  const belowAfter = creditsAfter < reserveTarget;
  const economyAction = isRunnerEconomyAction(input, action);
  const economyGain = economyAction && creditDelta > 0 ? creditDelta : 0;
  const economySpend =
    economyAction && creditDelta < 0 ? Math.abs(creditDelta) : 0;
  const runDiagnostics = runnerKnownPathDiagnosticsForAction(
    input,
    action,
    targetServerId,
    reserveTarget,
  );
  const remoteThreatTargeting = runnerRemoteThreatTargetingDiagnosticsForAction(
    input,
    action,
    targetServerId,
  );
  const spendBelowReserve =
    creditDelta < 0 &&
    belowAfter &&
    !runDiagnostics.probeRunWithPositiveInfoValue;
  const installCost =
    action.type === "install_card" ? actionCreditCost(action) : 0;
  const lowValueSpendBelowReserve =
    spendBelowReserve &&
    (isRunnerLowValueDuplicateInstall(input, action) ||
      (action.type === "start_run" &&
        (runDiagnostics.lowValueUnaffordableRun ||
          (runDiagnostics.runnerCentralRunStartedBelowReserve &&
            runnerHasVisibleRemoteScoreThreat(input)))) ||
      (action.type === "trash_accessed_card" &&
        runnerRemoteTrashAccessContext(input, action).role === "low_value"));
  const expensiveInstallBelowReserve =
    action.type === "install_card" && installCost >= 3 && belowAfter;
  const trashBlockedByCredits = runnerTrashBlockedByCredits(input);
  const stealBlockedByCredits = runnerStealBlockedByCredits(
    input,
    reserveTarget,
  );
  const contestBlockedByCredits =
    runnerContestBlockedByCredits(input, reserveTarget) ||
    runDiagnostics.runStartedAgainstKnownUnaffordablePath === true;
  const reserveAfterAccess = [
    "access_card",
    "steal_agenda",
    "trash_accessed_card",
    "decline_trash",
  ].includes(action.type)
    ? creditsAfter - reserveTarget
    : undefined;
  const accessTarget = targetServerId ?? input.playerView.run?.attackedServerId;

  return {
    runnerCreditsBefore: creditsBefore,
    runnerCreditsAfter: creditsAfter,
    runnerCreditDelta: creditDelta,
    runnerReserveTarget: reserveTarget,
    ...(belowBefore ? { runnerBelowReserveBefore: true } : {}),
    ...(belowAfter ? { runnerBelowReserveAfter: true } : {}),
    ...(economyGain > 0 ? { runnerEconomyCreditsGained: economyGain } : {}),
    ...(economySpend > 0 ? { runnerEconomyCreditsSpent: economySpend } : {}),
    ...(economyAction && economyGain > 0 && belowBefore
      ? { runnerReservePreservingEconomy: true }
      : {}),
    ...(contestBlockedByCredits ? { runnerContestBlockedByCredits: true } : {}),
    ...(trashBlockedByCredits ? { runnerTrashBlockedByCredits: true } : {}),
    ...(stealBlockedByCredits ? { runnerStealBlockedByCredits: true } : {}),
    ...(spendBelowReserve ? { runnerSpendBelowReserve: true } : {}),
    ...(lowValueSpendBelowReserve
      ? { runnerLowValueSpendBelowReserve: true }
      : {}),
    ...(expensiveInstallBelowReserve
      ? { runnerExpensiveInstallBelowReserve: true }
      : {}),
    ...(reserveAfterAccess !== undefined
      ? { runnerReserveAfterSuccessfulRun: reserveAfterAccess }
      : {}),
    ...(reserveAfterAccess !== undefined && isRemoteServerTarget(accessTarget)
      ? { runnerReserveAfterRemoteAccess: reserveAfterAccess }
      : {}),
    ...(reserveAfterAccess !== undefined &&
    (accessTarget === "hq" ||
      accessTarget === "rd" ||
      accessTarget === "archives")
      ? { runnerReserveAfterCentralRun: reserveAfterAccess }
      : {}),
    ...runDiagnostics,
    ...remoteThreatTargeting,
  };
}

type RunnerRemoteThreatProfile = {
  serverId: string;
  advanced: boolean;
  relevantTrash: boolean;
  blockedByBreakerCoverage: boolean;
  blockedByKnownIceCost: boolean;
  blockedByPostRunReserve: boolean;
  creditsAfterPath: number;
  postRunReserveTarget: number;
  contestable: boolean;
};

function runnerRemoteThreatTargetingDiagnosticsForAction(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (input.side !== "runner" || action.side !== "runner") return {};
  const legalRemoteProfiles = input.legalActions
    .filter(
      (candidate) =>
        candidate.type === "start_run" &&
        typeof candidate.payload?.serverId === "string" &&
        isRemoteServerTarget(candidate.payload.serverId),
    )
    .map((candidate) =>
      runnerRemoteThreatProfile(input, String(candidate.payload?.serverId)),
    );
  const advancedProfiles = legalRemoteProfiles.filter(
    (profile) => profile.advanced,
  );
  if (advancedProfiles.length === 0) return {};
  const contestableProfiles = advancedProfiles.filter(
    (profile) => profile.contestable,
  );
  const selectedProfile = targetServerId
    ? advancedProfiles.find((profile) => profile.serverId === targetServerId)
    : undefined;
  const centralRun =
    action.type === "start_run" &&
    (targetServerId === "hq" ||
      targetServerId === "rd" ||
      targetServerId === "archives");
  const centralJustified =
    centralRun && targetServerId
      ? runnerCentralRunHasClearPressureJustificationForInput(
          input,
          targetServerId,
          contestableProfiles.length > 0,
        )
      : false;
  const centralJustificationReasons =
    centralRun && targetServerId
      ? runnerCentralRunPressureJustificationReasonsForInput(
          input,
          targetServerId,
          contestableProfiles.length > 0,
        )
      : [];
  const centralBurnedReserve =
    centralRun &&
    targetServerId !== undefined &&
    contestableProfiles.length > 0 &&
    runnerCentralRunBurnsRemoteContestReserveForInput(
      input,
      targetServerId,
      contestableProfiles,
    );
  const contested =
    action.type === "start_run" &&
    targetServerId !== undefined &&
    selectedProfile !== undefined;
  const blockedByCredits = advancedProfiles.some(
    (profile) =>
      profile.blockedByKnownIceCost || profile.blockedByPostRunReserve,
  );
  const blockedByPostRunReserve = advancedProfiles.some(
    (profile) => profile.blockedByPostRunReserve,
  );
  const blockedByBreakerCoverage = advancedProfiles.some(
    (profile) => profile.blockedByBreakerCoverage,
  );
  const blockedByKnownIceCost = advancedProfiles.some(
    (profile) => profile.blockedByKnownIceCost,
  );
  return {
    runnerAdvancedRemoteThreatServerIds: advancedProfiles.map(
      (profile) => profile.serverId,
    ),
    ...(contestableProfiles.length > 0
      ? {
          runnerContestableAdvancedRemoteThreatServerIds:
            contestableProfiles.map((profile) => profile.serverId),
        }
      : {}),
    ...(contested
      ? { runnerContestedAdvancedRemoteServerId: selectedProfile.serverId }
      : {}),
    ...(centralRun && contestableProfiles.length > 0
      ? { runnerCentralRunInsteadOfContestableAdvancedRemote: true }
      : {}),
    ...(centralJustified ? { runnerCentralRunInsteadWasJustified: true } : {}),
    ...(centralRun && centralJustificationReasons[0]
      ? { runnerCentralRunJustificationReason: centralJustificationReasons[0] }
      : {}),
    ...(centralBurnedReserve
      ? { runnerCentralRunBurnedRemoteContestReserve: true }
      : {}),
    ...(blockedByCredits ? { runnerRemoteContestBlockedByCredits: true } : {}),
    ...(blockedByPostRunReserve
      ? { runnerRemoteContestBlockedByPostRunReserve: true }
      : {}),
    ...(blockedByBreakerCoverage
      ? { runnerRemoteContestBlockedByBreakerCoverage: true }
      : {}),
    ...(blockedByKnownIceCost
      ? { runnerRemoteContestBlockedByKnownIceCost: true }
      : {}),
    ...(centralRun && contestableProfiles.length > 0 && !centralJustified
      ? { runnerRepeatedCentralRunWhileSameRemoteThreat: true }
      : {}),
    ...(selectedProfile !== undefined && !selectedProfile.contestable
      ? { runnerRemoteRunStartedWithInsufficientPostRunReserve: true }
      : {}),
    ...(selectedProfile?.contestable === true
      ? { runnerRemoteRunStartedWithSufficientPostRunReserve: true }
      : {}),
  };
}

function runnerRemoteThreatProfile(
  input: AiDecisionInput,
  serverId: string,
): RunnerRemoteThreatProfile {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  const assessment = assessKnownRezzedIcePath(
    server?.ice ?? [],
    input.playerView.own.rig ?? [],
    input.playerView.own.credits,
    server?.root ?? [],
  );
  const visibleBreakCost = assessment.visibleBreakCost ?? 0;
  const creditsAfterPath = input.playerView.own.credits - visibleBreakCost;
  const postRunReserveTarget = runnerPostRunReserveTargetForRemoteInput(
    input,
    serverId,
  );
  const advanced = remoteServerHasScoreThreat(input, serverId);
  const relevantTrash = runnerRemoteHasKnownRelevantTrashTarget(
    input,
    serverId,
  );
  const blockedByKnownIceCost = visibleBreakCost > input.playerView.own.credits;
  const blockedByBreakerCoverage =
    assessment.blocked === true && !blockedByKnownIceCost;
  const blockedByPostRunReserve =
    !blockedByBreakerCoverage &&
    !blockedByKnownIceCost &&
    creditsAfterPath < postRunReserveTarget;
  return {
    serverId,
    advanced,
    relevantTrash,
    blockedByBreakerCoverage,
    blockedByKnownIceCost,
    blockedByPostRunReserve,
    creditsAfterPath,
    postRunReserveTarget,
    contestable:
      advanced &&
      !blockedByBreakerCoverage &&
      !blockedByKnownIceCost &&
      !blockedByPostRunReserve,
  };
}

function runnerPostRunReserveTargetForRemoteInput(
  input: AiDecisionInput,
  serverId: string,
): number {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  if (!server) return 3;
  let target = remoteServerHasScoreThreat(input, serverId) ? 1 : 2;
  const visibleStealTax = server.root.some(
    (card) =>
      card.known &&
      rolesForCardId(card.definitionId).some(
        (role) =>
          role.includes("agenda_steal_tax") ||
          role.includes("remote_upgrade_tax") ||
          role.includes("access_tax") ||
          role.includes("remote_agenda_protection") ||
          role.includes("scoring_protection") ||
          role.includes("protect_remote"),
      ),
  );
  if (visibleStealTax) target = Math.max(target, 6);
  const relevantTrashCosts = server.root
    .filter((card) => card.known)
    .filter((card) => {
      const role = remoteTrashRoleForVisibleCard(card);
      return role !== "low_value" && role !== "unknown";
    })
    .map((card) => remoteTrashCostForVisibleCard(card))
    .filter((cost): cost is number => typeof cost === "number");
  if (relevantTrashCosts.length > 0) {
    target = Math.max(target, Math.min(...relevantTrashCosts) + 1);
  }
  return Math.min(10, Math.max(1, Math.ceil(target)));
}

function runnerCentralRunHasClearPressureJustificationForInput(
  input: AiDecisionInput,
  targetServerId: string,
  contestableRemoteThreatVisible: boolean,
): boolean {
  return (
    runnerCentralRunPressureJustificationReasonsForInput(
      input,
      targetServerId,
      contestableRemoteThreatVisible,
    ).length > 0
  );
}

function runnerCentralRunPressureJustificationReasonsForInput(
  input: AiDecisionInput,
  targetServerId: string,
  contestableRemoteThreatVisible: boolean,
): string[] {
  if (
    targetServerId !== "hq" &&
    targetServerId !== "rd" &&
    targetServerId !== "archives"
  )
    return [];
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === targetServerId,
  );
  const assessment = assessKnownRezzedIcePath(
    server?.ice ?? [],
    input.playerView.own.rig ?? [],
    input.playerView.own.credits,
    server?.root ?? [],
  );
  if (assessment.blocked) return [];
  const visibleBreakCost = assessment.visibleBreakCost ?? 0;
  const installedTargets = new Set(
    (input.playerView.own.rig ?? [])
      .filter((card) =>
        isCentralPressureCardForMetrics(card.definitionId, true),
      )
      .flatMap((card) => centralPressureTargetsForCard(card.definitionId)),
  );
  const matchingInterface = installedTargets.has(
    targetServerId as "hq" | "rd" | "archives",
  );
  const hasAnyInterface = installedTargets.size > 0;
  const hasMultiaccess = (input.playerView.own.rig ?? []).some((card) =>
    rolesForCardId(card.definitionId).some((role) =>
      role.includes("multiaccess"),
    ),
  );
  const openOrCheap = visibleBreakCost <= 1 || (server?.ice.length ?? 0) === 0;
  const preservesReserve =
    input.playerView.own.credits - visibleBreakCost >=
    runnerCreditReserveTargetForInput(input);
  if (!openOrCheap || !preservesReserve) return [];
  const closeout = trueCentralCloseoutProfileForMetrics(
    input,
    targetServerId as "hq" | "rd" | "archives",
  ).opportunity;
  const hqPressure =
    targetServerId === "hq" && input.playerView.opponent.handCount >= 5;
  const rndFreshness =
    targetServerId === "rd" &&
    !recentCentralRunSameTargetWithoutRefresh(input, "rd");
  const remoteUncontestable = !contestableRemoteThreatVisible;
  const reasons = [
    ...(matchingInterface ? ["interface"] : []),
    ...(hasMultiaccess ? ["multiaccess"] : []),
    ...(closeout ? ["closeout"] : []),
    ...(remoteUncontestable ? ["remote_uncontestable"] : []),
    ...(hqPressure ? ["hq_pressure"] : []),
    ...(rndFreshness ? ["rnd_freshness"] : []),
    ...(!matchingInterface && hasAnyInterface ? ["generic_interface"] : []),
  ];
  if (contestableRemoteThreatVisible) {
    return reasons.filter((reason) =>
      [
        "interface",
        "multiaccess",
        "closeout",
        "hq_pressure",
        "rnd_freshness",
      ].includes(reason),
    );
  }
  return reasons;
}

function runnerCentralRunBurnsRemoteContestReserveForInput(
  input: AiDecisionInput,
  targetServerId: string,
  contestableProfiles: RunnerRemoteThreatProfile[],
): boolean {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === targetServerId,
  );
  const assessment = assessKnownRezzedIcePath(
    server?.ice ?? [],
    input.playerView.own.rig ?? [],
    input.playerView.own.credits,
    server?.root ?? [],
  );
  if (assessment.blocked || contestableProfiles.length === 0) return false;
  const visibleBreakCost = assessment.visibleBreakCost ?? 0;
  const creditsAfterPath = input.playerView.own.credits - visibleBreakCost;
  const requiredReserve = Math.max(
    ...contestableProfiles.map((profile) => profile.postRunReserveTarget),
  );
  return creditsAfterPath < requiredReserve;
}

function runnerCreditReserveTargetForInput(input: AiDecisionInput): number {
  if (input.side !== "runner") return 0;
  let target = 4;
  for (const server of input.playerView.servers) {
    if (!isRemoteServerTarget(server.id)) continue;
    const pathCost =
      assessKnownRezzedIcePath(
        server.ice,
        input.playerView.own.rig ?? [],
        input.playerView.own.credits,
        server.root,
      ).visibleBreakCost ?? 0;
    const hasThreat = server.root.some(
      (card) =>
        (card.advancementCounters ?? 0) > 0 ||
        (card.known && card.type === "agenda"),
    );
    const relevantTrashCosts = server.root
      .filter((card) => card.known)
      .filter((card) => {
        const role = remoteTrashRoleForVisibleCard(card);
        return role !== "low_value" && role !== "unknown";
      })
      .map((card) => remoteTrashCostForVisibleCard(card))
      .filter((cost): cost is number => typeof cost === "number");
    const cheapestRelevantTrash =
      relevantTrashCosts.length > 0 ? Math.min(...relevantTrashCosts) : 0;
    const visibleStealTax = server.root.some(
      (card) =>
        card.known &&
        rolesForCardId(card.definitionId).some(
          (role) =>
            role.includes("agenda_steal_tax") ||
            role.includes("remote_upgrade_tax") ||
            role.includes("access_tax"),
        ),
    )
      ? 5
      : 0;
    if (hasThreat) target = Math.max(target, pathCost + 3 + visibleStealTax);
    if (cheapestRelevantTrash > 0)
      target = Math.max(target, pathCost + cheapestRelevantTrash + 1);
  }
  return Math.min(12, Math.max(2, Math.ceil(target)));
}

function runnerKnownPathDiagnosticsForAction(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
  reserveTarget: number,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  const legalKnownNoAccessTargets = runnerKnownNoAccessLegalRunTargets(input);
  const selectedKnownNoAccess =
    targetServerId !== undefined &&
    legalKnownNoAccessTargets.some(
      (target) => target.serverId === targetServerId,
    );
  const suppressedKnownNoAccess =
    action.type !== "start_run" && legalKnownNoAccessTargets.length > 0;
  const firstProbeUnknownAllowed =
    action.type === "start_run" &&
    targetServerId !== undefined &&
    runnerRunTargetHasOnlyUnknownOrUnrezzedIce(input, targetServerId) &&
    legalKnownNoAccessTargets.length === 0;
  if (action.type === "jack_out") {
    const run = input.playerView.run;
    const server = input.playerView.servers.find(
      (candidate) => candidate.id === run?.attackedServerId,
    );
    const currentIce =
      run?.position?.kind === "ice"
        ? server?.ice[run.position.iceIndex]
        : undefined;
    if (
      currentIce?.known &&
      currentIce.rezzed === true &&
      (run?.position?.kind === "ice" ? run.position.iceIndex : 99) <= 1 &&
      assessKnownRezzedIcePath(
        [currentIce],
        input.playerView.own.rig ?? [],
        input.playerView.own.credits,
        server?.root ?? [],
      ).blocked
    ) {
      const fullPath =
        server !== undefined
          ? assessKnownRezzedIcePath(
              server.ice,
              input.playerView.own.rig ?? [],
              input.playerView.own.credits,
              server.root,
            )
          : undefined;
      return {
        runEndedAfterFirstIceDueToCredits: true,
        ...(fullPath?.canReachAccess === false &&
        fullPath.unpayableReason ===
          "later_ice_unaffordable_after_prior_ice_cost"
          ? { runnerRunAbortedAfterKnownUnpayableLaterIce: true }
          : {}),
      };
    }
    return {};
  }
  if (action.type !== "start_run" || !targetServerId) {
    const selectedCoverageRepair = runnerCoverageRepairDiagnostic(
      input,
      action,
    );
    const suppressedUnbreakableTarget = legalKnownNoAccessTargets.find(
      (target) =>
        runnerKnownPathAssessmentIsUnbreakableNoAccess(target.assessment),
    );
    const suppressedServerId = suppressedUnbreakableTarget?.serverId;
    const suppressedCentral =
      suppressedServerId === "hq" ||
      suppressedServerId === "rd" ||
      suppressedServerId === "archives";
    const suppressedRemote =
      suppressedServerId !== undefined &&
      isRemoteServerTarget(suppressedServerId);
    const selectedRemoteCoverageRepair =
      suppressedRemote &&
      (selectedCoverageRepair.runnerCoverageRepairIntentSearchTaken === true ||
        selectedCoverageRepair.runnerCoverageRepairIntentRecoveryTaken ===
          true ||
        selectedCoverageRepair.runnerCoverageRepairIntentInstallTaken ===
          true ||
        selectedCoverageRepair.runnerCoverageRepairIntentDrawOrEconomyTaken ===
          true);
    return {
      ...(suppressedKnownNoAccess
        ? {
            runnerRunSuppressedAsKnownNoAccess: true,
          }
        : {}),
      ...(suppressedUnbreakableTarget
        ? {
            runnerRepeatKnownUnbreakableRunSuppressed: true,
            runnerKnownPathAccessNotReachable: true,
            runnerKnownPathBlockedByUnbreakableIce: true,
          }
        : {}),
      ...(suppressedUnbreakableTarget?.assessment
        .knownPathBlockedByMissingCoverage
        ? { runnerKnownPathBlockedByMissingCoverage: true }
        : {}),
      ...(suppressedUnbreakableTarget?.assessment.knownPathBlockedByEtr
        ? { runnerKnownPathBlockedByKnownEtr: true }
        : {}),
      ...(suppressedUnbreakableTarget?.assessment.missingCoverage?.includes(
        "wall",
      )
        ? { runnerKnownPathBlockedByWall: true }
        : {}),
      ...(suppressedCentral
        ? {
            runnerCentralPressureSuppressedNoAccess: true,
            runnerMultiaccessValueSuppressedNoAccess: true,
          }
        : {}),
      ...(suppressedRemote
        ? {
            runnerKnownUnbreakableRemoteRunSuppressed: true,
            runnerKnownUnbreakableRemoteTraceSampled: true,
          }
        : {}),
      ...(suppressedRemote &&
      selectedCoverageRepair.runnerCoverageRepairIntentCandidates === true
        ? { runnerKnownUnbreakableRemoteCoverageRepairAvailable: true }
        : {}),
      ...(selectedRemoteCoverageRepair
        ? { runnerKnownUnbreakableRemoteCoverageRepairTaken: true }
        : {}),
      ...(suppressedServerId === "hq"
        ? { runnerHqInterfaceSuppressedNoAccess: true }
        : {}),
      ...(suppressedServerId === "rd"
        ? { runnerRndInterfaceSuppressedNoAccess: true }
        : {}),
      ...(suppressedServerId === "hq" &&
      suppressedUnbreakableTarget?.assessment.unbreakableIceTitle ===
        "Data Wall"
        ? {
            runnerDataWallHqNoAccessSuppressed: true,
            runnerHqInterfaceDataWallValueSuppressed: true,
          }
        : {}),
      ...(suppressedServerId === "hq" &&
      suppressedUnbreakableTarget?.assessment.unbreakableIceTitle ===
        "Data Wall" &&
      runnerHasRecentRunOnServer(input, suppressedServerId)
        ? { runnerDataWallHqRepeatSuppressed: true }
        : {}),
      ...selectedCoverageRepair,
    };
  }
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === targetServerId,
  );
  if (!server)
    return {
      ...(firstProbeUnknownAllowed
        ? { runnerRunAllowedAsFirstProbeUnknownIce: true }
        : {}),
    };
  const assessment = assessKnownRezzedIcePath(
    server.ice,
    input.playerView.own.rig ?? [],
    input.playerView.own.credits,
    server.root,
  );
  const knownPathCost = assessment.visibleBreakCost ?? 0;
  const creditsAfterPath = input.playerView.own.credits - knownPathCost;
  const creditsMissing = Math.max(
    0,
    knownPathCost - input.playerView.own.credits,
  );
  const remote = isRemoteServerTarget(targetServerId);
  const central =
    targetServerId === "hq" ||
    targetServerId === "rd" ||
    targetServerId === "archives";
  const remoteThreat = remoteServerHasScoreThreat(input, targetServerId);
  const positiveProbe =
    !remoteThreat &&
    (action.payload?.bypass === true ||
      rolesForAction(input, action).some(
        (role) =>
          role.includes("bypass") ||
          role.includes("probe") ||
          role.includes("expose") ||
          role.includes("inside_job"),
      ));
  const insufficientPath = assessment.blocked || creditsMissing > 0;
  const knownNoAccess =
    assessment.canReachAccess === false &&
    assessment.assessedKnownIceCount > 0 &&
    runnerKnownPathAssessmentIsKnownNoAccess(assessment);
  const knownUnbreakableNoAccess =
    knownNoAccess && runnerKnownPathAssessmentIsUnbreakableNoAccess(assessment);
  const canBreakNextButNotFull =
    assessment.canBreakNextIceButNotFullPath === true;
  const insufficientReserve =
    !insufficientPath &&
    creditsAfterPath < reserveTarget &&
    (remoteThreat ||
      runnerRemoteHasKnownRelevantTrashTarget(input, targetServerId));
  return {
    runKnownPathCostAtStart: knownPathCost,
    runCreditsAfterKnownPathEstimate: creditsAfterPath,
    runCreditsMissingForKnownPath: creditsMissing,
    ...(input.playerView.own.credits < reserveTarget
      ? { runnerRunStartedBelowReserve: true }
      : {}),
    ...(remote && input.playerView.own.credits < reserveTarget
      ? { runnerRemoteRunStartedBelowReserve: true }
      : {}),
    ...(central && input.playerView.own.credits < reserveTarget
      ? { runnerCentralRunStartedBelowReserve: true }
      : {}),
    ...(remoteThreat
      ? {
          runnerReserveBeforeAdvancedRemoteContest:
            input.playerView.own.credits - reserveTarget,
        }
      : {}),
    ...(insufficientPath
      ? { runStartedAgainstKnownUnaffordablePath: true }
      : {}),
    ...(insufficientPath && remote
      ? { remoteRunStartedAgainstKnownUnaffordablePath: true }
      : {}),
    ...(insufficientPath && central
      ? { centralRunStartedAgainstKnownUnaffordablePath: true }
      : {}),
    ...(knownNoAccess
      ? {
          runnerKnownPathCanReachAccessFalse: true,
        }
      : {}),
    ...(assessment.canReachAccess
      ? { runnerKnownPathAccessReachable: true }
      : assessment.assessedKnownIceCount > 0
        ? { runnerKnownPathAccessNotReachable: true }
        : {}),
    ...(knownNoAccess && !knownUnbreakableNoAccess
      ? { runnerRunStartedAgainstKnownUnpayableFullPath: true }
      : {}),
    ...(knownNoAccess && remote
      ? knownUnbreakableNoAccess
        ? {
            runnerRunStartedAgainstKnownUnbreakableRemotePath: true,
            runnerKnownUnbreakableRemoteTraceSampled: true,
            runnerKnownUnbreakableRemoteTrueBug: true,
            runnerKnownUnbreakableRemoteRunTakenDespiteGate: true,
          }
        : { runnerRunStartedAgainstKnownUnpayableRemotePath: true }
      : {}),
    ...(knownNoAccess && central
      ? knownUnbreakableNoAccess
        ? { runnerRunStartedAgainstKnownUnbreakableCentralPath: true }
        : { runnerRunStartedAgainstKnownUnpayableCentralPath: true }
      : {}),
    ...(knownUnbreakableNoAccess
      ? {
          runnerKnownPathBlockedByUnbreakableIce: true,
          runnerRunStartedAgainstKnownUnbreakablePath: true,
        }
      : {}),
    ...(assessment.knownPathBlockedByMissingCoverage
      ? { runnerKnownPathBlockedByMissingCoverage: true }
      : {}),
    ...(assessment.knownPathBlockedByEtr
      ? { runnerKnownPathBlockedByKnownEtr: true }
      : {}),
    ...(assessment.missingCoverage?.includes("wall")
      ? { runnerKnownPathBlockedByWall: true }
      : {}),
    ...(assessment.missingCoverage?.includes("code_gate")
      ? { runnerKnownPathBlockedByCodeGate: true }
      : {}),
    ...(assessment.missingCoverage?.includes("sentry")
      ? { runnerKnownPathBlockedBySentry: true }
      : {}),
    ...(knownUnbreakableNoAccess && central && targetServerId === "hq"
      ? { runnerHqInterfaceSuppressedNoAccess: true }
      : {}),
    ...(knownUnbreakableNoAccess && central && targetServerId === "rd"
      ? { runnerRndInterfaceSuppressedNoAccess: true }
      : {}),
    ...(knownUnbreakableNoAccess && central
      ? {
          runnerMultiaccessValueSuppressedNoAccess: true,
          runnerCentralPressureSuppressedNoAccess: true,
        }
      : {}),
    ...(knownUnbreakableNoAccess &&
    targetServerId === "hq" &&
    assessment.unbreakableIceTitle === "Data Wall"
      ? {
          runnerDataWallHqNoAccessSuppressed: true,
          runnerHqInterfaceDataWallValueSuppressed: true,
        }
      : {}),
    ...(knownUnbreakableNoAccess &&
    runnerHasRecentRunOnServer(input, targetServerId)
      ? {
          runnerRepeatKnownUnbreakableRunTakenDespiteSuppression: true,
          runnerRepeatKnownUnbreakableRunPenalized: true,
        }
      : {}),
    ...(knownUnbreakableNoAccess &&
    central &&
    runnerHasRecentRunOnServer(input, targetServerId)
      ? { runnerRepeatKnownUnbreakableCentralRunSuppressed: true }
      : {}),
    ...(knownUnbreakableNoAccess &&
    remote &&
    runnerHasRecentRunOnServer(input, targetServerId)
      ? {
          runnerRepeatKnownUnbreakableRemoteRunSuppressed: true,
          runnerKnownUnbreakableRemoteRunPenalized: true,
        }
      : {}),
    ...(knownUnbreakableNoAccess &&
    targetServerId === "hq" &&
    assessment.unbreakableIceTitle === "Data Wall" &&
    runnerHasRecentRunOnServer(input, targetServerId)
      ? { runnerDataWallHqRepeatSuppressed: true }
      : {}),
    ...(canBreakNextButNotFull
      ? { runnerKnownPathCanBreakNextIceButNotFullPath: true }
      : {}),
    ...(assessment.creditsSpentBeforeUnpayableIce > 0
      ? { runnerRunSpentCreditsBeforeKnownUnbreakableLaterIce: true }
      : {}),
    ...(knownNoAccess &&
    (assessment.visibleBreakCost ?? 0) > input.playerView.own.credits
      ? { runnerRunCostQuoteUnderestimatedFullPath: true }
      : {}),
    ...(knownNoAccess && runnerHasRecentRunOnServer(input, targetServerId)
      ? { runnerRepeatRunOnKnownUnpayablePath: true }
      : {}),
    ...(knownNoAccess &&
    remote &&
    runnerHasRecentRunOnServer(input, targetServerId)
      ? { runnerRepeatRunOnKnownUnpayableRemotePath: true }
      : {}),
    ...(knownNoAccess && positiveProbe
      ? { runnerRunCouldOnlyForceRezButNotAccess: true }
      : {}),
    ...(firstProbeUnknownAllowed
      ? { runnerRunAllowedAsFirstProbeUnknownIce: true }
      : {}),
    ...(selectedKnownNoAccess
      ? { runnerRunPenalizedAsKnownNoAccess: true }
      : {}),
    ...(insufficientReserve
      ? { runStartedWithInsufficientStealOrTrashReserve: true }
      : {}),
    ...(positiveProbe ? { probeRunWithPositiveInfoValue: true } : {}),
    ...(insufficientPath && !positiveProbe && !remoteThreat
      ? { lowValueUnaffordableRun: true }
      : {}),
  };
}

function runnerKnownNoAccessLegalRunTargets(
  input: AiDecisionInput,
): Array<{ serverId: string; assessment: KnownRezzedIcePathAssessment }> {
  if (input.side !== "runner") return [];
  return input.legalActions
    .filter(
      (action) =>
        action.side === "runner" &&
        action.type === "start_run" &&
        typeof action.payload?.serverId === "string",
    )
    .map((action) => {
      const serverId = String(action.payload?.serverId);
      const server = input.playerView.servers.find(
        (candidate) => candidate.id === serverId,
      );
      if (!server) return undefined;
      const assessment = assessKnownRezzedIcePath(
        server.ice,
        input.playerView.own.rig ?? [],
        input.playerView.own.credits,
        server.root,
      );
      if (
        assessment.canReachAccess ||
        assessment.assessedKnownIceCount <= 0 ||
        !runnerKnownPathAssessmentIsKnownNoAccess(assessment) ||
        runnerRunTargetHasOnlyUnknownOrUnrezzedIce(input, serverId)
      )
        return undefined;
      return { serverId, assessment };
    })
    .filter(
      (
        target,
      ): target is {
        serverId: string;
        assessment: KnownRezzedIcePathAssessment;
      } => target !== undefined,
    );
}

function runnerCoverageRepairDiagnostic(
  input: AiDecisionInput,
  action: LegalAction,
): Partial<AiSimulationSummary["actionSequence"][number]> {
  if (runnerKnownNoAccessLegalRunTargets(input).length === 0) return {};
  const definitionId =
    typeof action.source === "string"
      ? findVisibleCard(input, action.source)?.definitionId
      : undefined;
  const roles = definitionId ? rolesForCardId(definitionId) : [];
  const actionKind = action.type;
  const isSearchOrRecovery =
    roles.some(
      (role) =>
        role.includes("search") ||
        role.includes("tutor") ||
        role.includes("recovery") ||
        role.includes("trash_recovery"),
    ) || actionKind === "resolve_choice";
  const isRecovery = roles.some(
    (role) => role.includes("recovery") || role.includes("trash_recovery"),
  );
  const isInstall = actionKind === "install_card";
  const isDrawOrEconomy =
    actionKind === "draw_card" ||
    actionKind === "gain_credit" ||
    (actionKind === "play_event" && roles.some((role) => role === "economy"));
  return {
    runnerCoverageRepairIntentCandidates: true,
    ...(isSearchOrRecovery && !isRecovery
      ? { runnerCoverageRepairIntentSearchTaken: true }
      : {}),
    ...(isRecovery ? { runnerCoverageRepairIntentRecoveryTaken: true } : {}),
    ...(isInstall ? { runnerCoverageRepairIntentInstallTaken: true } : {}),
    ...(isDrawOrEconomy
      ? { runnerCoverageRepairIntentDrawOrEconomyTaken: true }
      : {}),
    ...(isSearchOrRecovery || isInstall || isDrawOrEconomy
      ? { runnerCoverageRepairIntentSatisfied: true }
      : { runnerCoverageRepairIntentNoFollowup: true }),
  };
}

function runnerRunTargetHasOnlyUnknownOrUnrezzedIce(
  input: AiDecisionInput,
  serverId: string,
): boolean {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  return (
    server !== undefined &&
    server.ice.length > 0 &&
    server.ice.every((ice) => !ice.known || ice.rezzed !== true)
  );
}

function runnerHasRecentRunOnServer(
  input: AiDecisionInput,
  serverId: string,
): boolean {
  return input.playerView.publicEvents
    .slice(-24)
    .some(
      (event) =>
        event.publicPayload.actionType === "start_run" &&
        aiServerIdFromEvent(event) === serverId,
    );
}

function runnerContestBlockedByCredits(
  input: AiDecisionInput,
  reserveTarget: number,
): boolean {
  return input.legalActions.some((action) => {
    if (
      action.side !== "runner" ||
      action.type !== "start_run" ||
      typeof action.payload?.serverId !== "string" ||
      !isRemoteServerTarget(action.payload.serverId) ||
      !remoteServerHasScoreThreat(input, action.payload.serverId)
    )
      return false;
    const server = input.playerView.servers.find(
      (candidate) => candidate.id === action.payload?.serverId,
    );
    if (!server) return false;
    const path =
      assessKnownRezzedIcePath(
        server.ice,
        input.playerView.own.rig ?? [],
        input.playerView.own.credits,
        server.root,
      ).visibleBreakCost ?? 0;
    return (
      input.playerView.own.credits < path ||
      input.playerView.own.credits - path < Math.min(3, reserveTarget - 2)
    );
  });
}

function runnerTrashBlockedByCredits(input: AiDecisionInput): boolean {
  const run = input.playerView.run;
  const accessed = run?.accessedCard;
  if (!run || !isRemoteServerTarget(run.attackedServerId) || !accessed?.known)
    return false;
  const trashCost = remoteTrashCostForVisibleCard(accessed);
  if (trashCost === undefined) return false;
  const role = remoteTrashRoleForVisibleCard(accessed);
  if (role === "low_value" || role === "unknown") return false;
  return (
    input.playerView.own.credits < trashCost &&
    !input.legalActions.some((action) => action.type === "trash_accessed_card")
  );
}

function runnerStealBlockedByCredits(
  input: AiDecisionInput,
  reserveTarget: number,
): boolean {
  const run = input.playerView.run;
  const accessed = run?.accessedCard;
  if (!run || !accessed?.known || accessed.type !== "agenda") return false;
  return (
    !input.legalActions.some((action) => action.type === "steal_agenda") &&
    input.playerView.own.credits < reserveTarget
  );
}

function runnerHasVisibleRemoteScoreThreat(input: AiDecisionInput): boolean {
  return input.playerView.servers.some(
    (server) =>
      isRemoteServerTarget(server.id) &&
      remoteServerHasScoreThreat(input, server.id),
  );
}

function runnerRemoteHasKnownRelevantTrashTarget(
  input: AiDecisionInput,
  serverId: string,
): boolean {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  if (!server) return false;
  return server.root.some((card) => {
    if (!card.known || remoteTrashCostForVisibleCard(card) === undefined)
      return false;
    const role = remoteTrashRoleForVisibleCard(card);
    return role !== "low_value" && role !== "unknown";
  });
}

function runnerRemoteTrashAccessContext(
  input: AiDecisionInput,
  action: LegalAction,
): {
  trashable: boolean;
  relevant: boolean;
  affordableRelevant: boolean;
  relevantTaken: boolean;
  skippedAffordableRelevant: boolean;
  expensive: boolean;
  highImpact: boolean;
  acuteThreat: boolean;
  trashCost: number;
  generalCreditCost: number;
  dedicatedTrashCredits: number;
  creditsAfterGeneralTrash: number;
  reserveTarget: number;
  dropsBelowReserve: boolean;
  deferredByBudget: boolean;
  finitePoolEconomy: boolean;
  bbsWhisperingCampaign: boolean;
  corpValueRemaining: number;
  legalTrashActionCount: number;
  centralAccess: boolean;
  allInGeneralTrash: boolean;
  accessServerId?: string;
  evidence: string[];
  targetType?: RemoteTrashTargetType;
  role?: RemoteTrashRole;
} {
  const run = input.playerView.run;
  const accessed = run?.accessedCard;
  const accessServerId = run?.attackedServerId;
  const centralAccess = accessServerId === "hq" || accessServerId === "rd";
  const remoteAccess = isRemoteServerTarget(accessServerId);
  if (!run || (!remoteAccess && !centralAccess) || !accessed?.known) {
    return {
      trashable: false,
      relevant: false,
      affordableRelevant: false,
      relevantTaken: false,
      skippedAffordableRelevant: false,
      expensive: false,
      highImpact: false,
      acuteThreat: false,
      trashCost: 0,
      generalCreditCost: 0,
      dedicatedTrashCredits: 0,
      creditsAfterGeneralTrash: input.playerView.own.credits,
      reserveTarget: runnerCreditReserveTargetForInput(input),
      dropsBelowReserve: false,
      deferredByBudget: false,
      finitePoolEconomy: false,
      bbsWhisperingCampaign: false,
      corpValueRemaining: 0,
      legalTrashActionCount: 0,
      centralAccess: false,
      allInGeneralTrash: false,
      ...(accessServerId ? { accessServerId } : {}),
      evidence: ["remote_trash_access:none"],
    };
  }
  const targetType = remoteTrashTargetTypeForVisibleCard(accessed);
  const structuredRemoteRole = getStructuredRemoteRoleForCard(
    accessed.definitionId,
  );
  const role = remoteTrashRoleForAccessedVisibleCard(input, accessed);
  const trashAction = input.legalActions.find(
    (candidate) => candidate.type === "trash_accessed_card",
  );
  const legalTrashActionCount = input.legalActions.filter(
    (candidate) => candidate.type === "trash_accessed_card",
  ).length;
  const trashCost = trashAction
    ? remoteTrashActionTotalCostForMetrics(trashAction)
    : (remoteTrashCostForVisibleCard(accessed) ?? 0);
  const trashable =
    targetType !== "unknown" &&
    remoteTrashCostForVisibleCard(accessed) !== undefined;
  const bbsWhisperingCampaign =
    accessed.definitionId === BBS_WHISPERING_CAMPAIGN_DEFINITION_ID;
  const corpValueRemaining = remoteTrashVisibleCorpValueRemaining(accessed);
  const finitePoolEconomy =
    bbsWhisperingCampaign ||
    (role === "economy" &&
      (corpValueRemaining > 0 ||
        remoteTrashCardLooksLikeFinitePoolForMetrics(accessed)));
  const relevant =
    trashable &&
    ((role !== "low_value" && role !== "unknown") || finitePoolEconomy);
  const dedicatedTrashCredits =
    trashAction !== undefined
      ? remoteTrashDedicatedCreditsForMetrics(input, trashAction, accessed)
      : 0;
  const generalCreditCost = Math.max(0, trashCost - dedicatedTrashCredits);
  const reserveTarget = runnerCreditReserveTargetForInput(input);
  const creditsAfterGeneralTrash =
    input.playerView.own.credits - generalCreditCost;
  const dropsBelowReserve =
    trashable && creditsAfterGeneralTrash < Math.max(2, reserveTarget - 1);
  const allInGeneralTrash =
    trashable &&
    generalCreditCost > 0 &&
    generalCreditCost >= input.playerView.own.credits &&
    dedicatedTrashCredits <= 0;
  const expensive = trashCost >= 4 || generalCreditCost >= 4;
  const highImpact =
    relevant &&
    (role === "scoring_protection" ||
      role === "run_tax" ||
      role === "remote_capacity" ||
      role === "economy" ||
      role === "tag_punish" ||
      finitePoolEconomy);
  const acuteThreat = remoteAccess
    ? remoteTrashAccessProtectsAcuteThreatForMetrics(
        input,
        run.attackedServerId,
      )
    : false;
  const highRemainingFinitePool =
    finitePoolEconomy &&
    corpValueRemaining >= Math.max(trashCost + 2, 8) &&
    trashCost > 0;
  const centralBudgetDeferral =
    centralAccess &&
    allInGeneralTrash &&
    !acuteThreat &&
    !highRemainingFinitePool;
  const deferredByBudget =
    centralBudgetDeferral ||
    (trashable &&
      highImpact &&
      expensive &&
      dropsBelowReserve &&
      dedicatedTrashCredits <= 0 &&
      !acuteThreat &&
      !highRemainingFinitePool);
  const affordableRelevant =
    relevant && trashAction !== undefined && !deferredByBudget;
  const relevantTaken =
    affordableRelevant && action.type === "trash_accessed_card";
  const accessDecisionProjection = projectAccessWindowChoice({
    actionType: action.type,
    serverId: accessServerId,
    ...(accessed.definitionId
      ? { knownRootDefinitionId: accessed.definitionId }
      : {}),
    targetType,
    trashCost,
    generalTrashCost: generalCreditCost,
    dedicatedTrashCredits,
    reserveWouldBreak: deferredByBudget,
    finitePoolValueRemaining: corpValueRemaining,
  });
  return {
    trashable,
    relevant,
    affordableRelevant,
    relevantTaken,
    skippedAffordableRelevant:
      affordableRelevant && action.type !== "trash_accessed_card",
    expensive,
    highImpact,
    acuteThreat,
    trashCost,
    generalCreditCost,
    dedicatedTrashCredits,
    creditsAfterGeneralTrash,
    reserveTarget,
    dropsBelowReserve,
    deferredByBudget,
    finitePoolEconomy,
    bbsWhisperingCampaign,
    corpValueRemaining,
    legalTrashActionCount,
    centralAccess,
    allInGeneralTrash,
    evidence: [
      `access_trash_scope:${centralAccess ? "central" : "remote"}`,
      `access_trash_server:${accessServerId}`,
      `remote_trash_role:${role}`,
      ...(structuredRemoteRole
        ? [
            "runner_remote_role_profile_seen:true",
            `runner_remote_role_kind:${structuredRemoteRole.kind}`,
            ...(structuredRemoteRole.serverScope
              ? [
                  `runner_remote_role_server_scope:${structuredRemoteRole.serverScope}`,
                ]
              : []),
            ...(relevant
              ? ["runner_remote_role_used_for_trash_value:true"]
              : []),
            ...(deferredByBudget
              ? ["runner_remote_role_trash_budget_preserved:true"]
              : []),
          ]
        : []),
      `remote_trash_cost:${trashCost}`,
      `remote_trash_general_credit_cost:${generalCreditCost}`,
      `remote_trash_dedicated_credits:${dedicatedTrashCredits}`,
      `remote_trash_credits_after:${creditsAfterGeneralTrash}`,
      `remote_trash_reserve_target:${reserveTarget}`,
      `remote_trash_drops_below_reserve:${dropsBelowReserve}`,
      `remote_trash_acute_threat:${acuteThreat}`,
      `remote_trash_deferred_by_budget:${deferredByBudget}`,
      `central_access_trash:${centralAccess}`,
      `central_access_trash_all_in_budget_risk:${centralBudgetDeferral}`,
      `remote_trash_finite_pool_economy:${finitePoolEconomy}`,
      `remote_trash_bbs_whispering_campaign:${bbsWhisperingCampaign}`,
      `remote_trash_corp_value_remaining:${corpValueRemaining}`,
      ...accessDecisionProjection.evidence,
    ],
    ...(accessServerId ? { accessServerId } : {}),
    ...(trashable ? { targetType } : {}),
    ...(trashable ? { role } : {}),
  };
}

function remoteTrashVisibleCorpValueRemaining(card: VisibleCard): number {
  return Math.max(
    0,
    card.counters?.bit ?? 0,
    card.counters?.recurring_credit ?? 0,
  );
}

function remoteTrashCardLooksLikeFinitePoolForMetrics(
  card: VisibleCard,
): boolean {
  if (card.definitionId === BBS_WHISPERING_CAMPAIGN_DEFINITION_ID) return true;
  const runtimeDefinition = card.definitionId
    ? RUNTIME_CARDS[card.definitionId]
    : undefined;
  const demoDefinition = card.definitionId
    ? DEMO_CARDS_BY_ID[card.definitionId]
    : undefined;
  const mechanics = [
    ...("mechanics" in (runtimeDefinition ?? {})
      ? ((runtimeDefinition as { mechanics?: string[] } | undefined)
          ?.mechanics ?? [])
      : []),
    ...(demoDefinition?.mechanics ?? []),
  ];
  const runtimeText =
    (runtimeDefinition as { text?: string } | undefined)?.text ?? "";
  const demoText =
    (demoDefinition as { text?: string } | undefined)?.text ?? "";
  const rulesText = `${runtimeText} ${demoText} ${
    card.rulesText ?? ""
  }`.toLowerCase();
  return (
    mechanics.some(
      (mechanic: string) =>
        mechanic.includes("finite_economy_pool") ||
        mechanic.includes("hosted_credits") ||
        mechanic.includes("bit_counter"),
    ) ||
    (rulesText.includes("put") &&
      rulesText.includes("from the bank") &&
      rulesText.includes("take") &&
      rulesText.includes("bits"))
  );
}

function runnerAdvancedRemoteContestContext(
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
): {
  opportunity: boolean;
  taken: boolean;
  skipped: boolean;
  centralWhileThreat: boolean;
  reserveAfterRun?: number;
} {
  if (input.side !== "runner") {
    return {
      opportunity: false,
      taken: false,
      skipped: false,
      centralWhileThreat: false,
    };
  }
  const advancedRemoteTargets = new Set(
    input.legalActions
      .filter(
        (candidate) =>
          candidate.type === "start_run" &&
          typeof candidate.payload?.serverId === "string" &&
          isRemoteServerTarget(candidate.payload.serverId) &&
          remoteServerHasScoreThreat(input, candidate.payload.serverId),
      )
      .map((candidate) => String(candidate.payload?.serverId)),
  );
  const opportunity = advancedRemoteTargets.size > 0;
  const taken =
    action.type === "start_run" &&
    targetServerId !== undefined &&
    advancedRemoteTargets.has(targetServerId);
  const centralWhileThreat =
    opportunity &&
    action.type === "start_run" &&
    (targetServerId === "hq" ||
      targetServerId === "rd" ||
      targetServerId === "archives");
  return {
    opportunity,
    taken,
    skipped: opportunity && !taken,
    centralWhileThreat,
    ...(action.type === "start_run" &&
    targetServerId !== undefined &&
    isRemoteServerTarget(targetServerId)
      ? {
          reserveAfterRun:
            input.playerView.own.credits - actionCreditCost(action),
        }
      : {}),
  };
}

function runnerDrawKindForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
): { draw: boolean; click: boolean; cardEffect: boolean } {
  if (action.type === "draw_card")
    return { draw: true, click: true, cardEffect: false };
  const roles = rolesForAction(input, action);
  const cardEffect =
    (action.type === "play_event" ||
      action.type === "trigger_ability" ||
      action.type === "activated_card_ability") &&
    roles.some(
      (role) => role === "draw" || role === "setup" || role.includes("search"),
    );
  const searchChoice =
    action.type === "resolve_choice" &&
    input.playerView.pendingChoice !== undefined &&
    isSearchChoice(input.playerView.pendingChoice);
  return {
    draw: cardEffect || searchChoice,
    click: false,
    cardEffect: cardEffect || searchChoice,
  };
}

function hasRunnerPlayableEconomyAction(
  input: AiDecisionInput,
  excludeActionId?: string,
): boolean {
  return input.legalActions.some(
    (action) =>
      action.actionId !== excludeActionId &&
      action.side === "runner" &&
      isRunnerEconomyAction(input, action) &&
      action.source !== "basic_action" &&
      action.source !== "game_rule",
  );
}

function hasRunnerInstallableBreakerAction(
  input: AiDecisionInput,
  excludeActionId?: string,
): boolean {
  return input.legalActions.some(
    (action) =>
      action.actionId !== excludeActionId &&
      action.side === "runner" &&
      action.type === "install_card" &&
      rolesForAction(input, action).some((role) => role.startsWith("breaker_")),
  );
}

function hasRunnerRunnablePressureAction(
  input: AiDecisionInput,
  excludeActionId?: string,
): boolean {
  return input.legalActions.some((action) => {
    if (action.actionId === excludeActionId || action.side !== "runner")
      return false;
    if (isRunnerPressureAction(input, action)) return true;
    if (action.type !== "start_run") return false;
    const serverId =
      typeof action.payload?.serverId === "string"
        ? action.payload.serverId
        : "";
    if (!serverId) return false;
    const server = input.playerView.servers.find(
      (candidate) => candidate.id === serverId,
    );
    if (serverId.startsWith("remote_") && (server?.root.length ?? 0) === 0)
      return false;
    return input.playerView.own.credits >= 3 || (server?.ice.length ?? 0) === 0;
  });
}

function hasRunnerRemoteTrashAction(input: AiDecisionInput): boolean {
  return input.legalActions.some(
    (action) =>
      action.side === "runner" &&
      action.type === "trash_accessed_card" &&
      isRemoteServerTarget(input.playerView.run?.attackedServerId),
  );
}

function remoteServerHasScoreThreat(
  input: AiDecisionInput,
  serverId: string,
): boolean {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  if (!server) return false;
  return server.root.some(
    (card) =>
      (card.advancementCounters ?? 0) > 0 ||
      (card.known && card.type === "agenda"),
  );
}

function remoteTrashTargetTypeForVisibleCard(
  card: VisibleCard,
): RemoteTrashTargetType {
  if (card.type === "asset") return "asset_node";
  if (card.type === "upgrade") return "upgrade";
  if (card.type === "ice") return "ice";
  return "unknown";
}

function remoteTrashRoleForAccessedVisibleCard(
  input: AiDecisionInput,
  card: VisibleCard,
): RemoteTrashRole {
  const role = remoteTrashRoleForVisibleCard(card);
  if (role !== "unknown") return role;
  if (accessedCardContributesToVisibleRunTaxForMetrics(input, card))
    return "run_tax";
  return role;
}

function remoteTrashRoleForVisibleCard(card: VisibleCard): RemoteTrashRole {
  if (card.definitionId === "simple_upgrade") return "low_value";
  const structuredRole = getStructuredRemoteRoleForCard(card.definitionId);
  if (structuredRole) {
    if (structuredRole.kind === "remote_capacity") return "remote_capacity";
    if (structuredRole.kind === "asset_economy") return "economy";
    if (structuredRole.kind === "bait" || structuredRole.kind === "ambush")
      return "ambush";
    if (
      structuredRole.kind === "run_tax" ||
      structuredRole.kind === "tax_fort" ||
      structuredRole.kind === "ice_modifier"
    )
      return "run_tax";
    if (
      remoteRoleIsScoringProtectionKind(structuredRole.kind) &&
      !remoteRoleIsNonScoringProtectionKind(structuredRole.kind)
    )
      return "scoring_protection";
  }
  const roles = rolesForCardId(card.definitionId);
  const runtimeDefinition = card.definitionId
    ? RUNTIME_CARDS[card.definitionId]
    : undefined;
  const demoDefinition = card.definitionId
    ? DEMO_CARDS_BY_ID[card.definitionId]
    : undefined;
  const mechanics = [
    ...("mechanics" in (runtimeDefinition ?? {})
      ? ((runtimeDefinition as { mechanics?: string[] } | undefined)
          ?.mechanics ?? [])
      : []),
    ...(demoDefinition?.mechanics ?? []),
  ];
  const subtypes = [
    ...(runtimeDefinition?.subtypes ?? []),
    ...(demoDefinition?.subtypes ?? []),
  ];
  if (
    roles.some(
      (role) =>
        role.includes("agenda_steal_tax") ||
        role.includes("access_tax") ||
        role.includes("remote_agenda_protection") ||
        role.includes("scoring") ||
        role.includes("protect_remote") ||
        role.includes("remote_upgrade_tax"),
    )
  )
    return "scoring_protection";
  if (
    roles.some(
      (role) =>
        role.includes("run_tax") ||
        role.includes("ice_tax") ||
        role.includes("access_tax") ||
        role.includes("server_tax"),
    ) ||
    mechanics.some(
      (mechanic: string) =>
        mechanic.includes("break_subroutine_cost") ||
        mechanic.includes("trash_cost_modifier") ||
        mechanic.includes("trace_bid_credit_source") ||
        mechanic.includes("run_flow"),
    ) ||
    subtypes.some((subtype) => subtype.toLowerCase() === "region")
  )
    return "run_tax";
  if (
    roles.some((role) => role.includes("remote_capacity")) ||
    mechanics.some((mechanic: string) => mechanic.includes("remote_capacity"))
  )
    return "remote_capacity";
  if (roles.some((role) => role.includes("economy"))) return "economy";
  if (
    roles.some(
      (role) =>
        role.includes("tag") ||
        role.includes("trace") ||
        role.includes("punish") ||
        role.includes("damage"),
    )
  )
    return "tag_punish";
  if (roles.some((role) => role.includes("ambush") || role.includes("trap")))
    return "ambush";
  if (roles.some((role) => role.includes("low_value"))) return "low_value";
  if (card.type === "asset" || card.type === "upgrade") return "unknown";
  return "unknown";
}

function remoteTrashActionTotalCostForMetrics(action: LegalAction): number {
  const payloadCost = action.payload?.accessTrashTotalCost;
  return typeof payloadCost === "number" && Number.isFinite(payloadCost)
    ? payloadCost
    : actionCreditCost(action);
}

function remoteTrashDedicatedCreditsForMetrics(
  input: AiDecisionInput,
  action: LegalAction,
  accessed: VisibleCard,
): number {
  const scatter =
    accessed.type === "upgrade" &&
    typeof action.payload?.scatterShotRecurringCreditsAvailable === "number"
      ? action.payload.scatterShotRecurringCreditsAvailable
      : 0;
  const poltergeist =
    accessed.type === "asset" &&
    typeof action.payload?.poltergeistRecurringCreditsAvailable === "number"
      ? action.payload.poltergeistRecurringCreditsAvailable
      : 0;
  const payloadCredits = scatter + poltergeist;
  const rigCredits =
    input.playerView.own.rig?.reduce((sum, card) => {
      const runtimeDefinition = card.definitionId
        ? RUNTIME_CARDS[card.definitionId]
        : undefined;
      const demoDefinition = card.definitionId
        ? DEMO_CARDS_BY_ID[card.definitionId]
        : undefined;
      const mechanics = [
        ...("mechanics" in (runtimeDefinition ?? {})
          ? ((runtimeDefinition as { mechanics?: string[] } | undefined)
              ?.mechanics ?? [])
          : []),
        ...(demoDefinition?.mechanics ?? []),
      ];
      const supportsUpgradeTrash =
        accessed.type === "upgrade" &&
        mechanics.some((mechanic: string) =>
          mechanic.includes("upgrade_trash_payment"),
        );
      const supportsAssetTrash =
        accessed.type === "asset" &&
        mechanics.some((mechanic: string) =>
          mechanic.includes("node_trash_recurring_credit"),
        );
      if (!supportsUpgradeTrash && !supportsAssetTrash) return sum;
      return (
        sum + (card.counters?.recurring_credit ?? 0) + (card.counters?.bit ?? 0)
      );
    }, 0) ?? 0;
  return Math.min(
    remoteTrashActionTotalCostForMetrics(action),
    Math.max(payloadCredits, rigCredits),
  );
}

function remoteTrashAccessProtectsAcuteThreatForMetrics(
  input: AiDecisionInput,
  serverId: string,
): boolean {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  if (!server) return false;
  if (remoteServerHasScoreThreat(input, serverId)) return true;
  return server.root.some((card) => {
    if (!card.known || card.type !== "agenda" || !card.definitionId)
      return false;
    return (
      input.playerView.own.agendaPoints +
        (RUNTIME_CARDS[card.definitionId]?.numeric.agendaPoints ??
          DEMO_CARDS_BY_ID[card.definitionId]?.agendaPoints ??
          0) >=
      input.playerView.agendaPointsToWin - 1
    );
  });
}

function accessedCardContributesToVisibleRunTaxForMetrics(
  input: AiDecisionInput,
  accessed: VisibleCard,
): boolean {
  const definitionId = accessed.definitionId;
  if (!definitionId) return false;
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === input.playerView.run?.attackedServerId,
  );
  return (
    server?.ice.some((ice) =>
      ice.effectiveRunQuote?.subroutines.some(
        (subroutine) => subroutine.sourceDefinitionId === definitionId,
      ),
    ) === true ||
    server?.ice.some((ice) =>
      ice.effectiveRunQuote?.breakSubroutineCostSourceDefinitionIds?.includes(
        definitionId,
      ),
    ) === true
  );
}

function remoteTrashCostForVisibleCard(card: VisibleCard): number | undefined {
  if (!card.known || !card.definitionId) return undefined;
  return (
    card.trashCost ??
    RUNTIME_CARDS[card.definitionId]?.numeric.trashCost ??
    DEMO_CARDS_BY_ID[card.definitionId]?.trashCost
  );
}

function remoteTrashCostBucket(cost: number): "0_1" | "2_3" | "4_5" | "6_plus" {
  if (cost <= 1) return "0_1";
  if (cost <= 3) return "2_3";
  if (cost <= 5) return "4_5";
  return "6_plus";
}

function actionCreditCost(action: LegalAction): number {
  return action.costs.reduce(
    (sum, cost) =>
      sum + (Number.isFinite(cost.credits) ? (cost.credits ?? 0) : 0),
    0,
  );
}

function isRunnerEconomyAction(
  input: AiDecisionInput,
  action: LegalAction,
): boolean {
  if (action.side !== "runner") return false;
  if (action.type === "gain_credit") return true;
  if (
    action.type !== "play_event" &&
    action.type !== "install_card" &&
    action.type !== "trigger_ability" &&
    action.type !== "activated_card_ability"
  )
    return false;
  return rolesForAction(input, action).some((role) =>
    isRunnerEconomyRole(role),
  );
}

function isRunnerRigInstallAction(
  input: AiDecisionInput,
  action: LegalAction,
): boolean {
  if (action.type !== "install_card") return false;
  const roles = rolesForAction(input, action);
  return roles.some(
    (role) =>
      role.startsWith("breaker_") ||
      role === "memory" ||
      role === "memory_support" ||
      role === "setup" ||
      role === "build_rig" ||
      isRunnerPressureRole(role),
  );
}

function isRunnerPressureAction(
  input: AiDecisionInput,
  action: LegalAction,
): boolean {
  if (action.side !== "runner") return false;
  const roles = rolesForAction(input, action);
  return (
    action.type === "start_run" ||
    roles.some((role) => isRunnerPressureRole(role))
  );
}

function runnerDiscardChoiceRoles(
  input: AiDecisionInput,
  decision: AiDecision,
): string[] {
  if (
    input.playerView.pendingChoice?.source !== "discard_phase" ||
    input.playerView.pendingChoice.kind !== "select_cards" ||
    decision.selectedChoices === undefined
  )
    return [];
  const selected = decision.selectedChoices as
    | { choiceId?: unknown; selectedOptionIds?: unknown }
    | undefined;
  if (
    selected?.choiceId !== input.playerView.pendingChoice.choiceId ||
    !Array.isArray(selected.selectedOptionIds)
  )
    return [];
  const selectedIds = new Set(
    selected.selectedOptionIds.filter(
      (optionId): optionId is string => typeof optionId === "string",
    ),
  );
  return input.playerView.pendingChoice.options
    .filter((option) => selectedIds.has(option.id))
    .flatMap((option) => discardRolesForCardId(option.card?.definitionId));
}

function isRunnerDuplicateInstall(
  input: AiDecisionInput,
  action: LegalAction,
): boolean {
  const definitionId = sourceDefinitionIdForSimulationAction(input, action);
  if (!definitionId || action.type !== "install_card") return false;
  return (
    input.playerView.own.rig?.some(
      (card) => card.known && card.definitionId === definitionId,
    ) === true
  );
}

function isRunnerLowValueDuplicateInstall(
  input: AiDecisionInput,
  action: LegalAction,
): boolean {
  const definitionId = sourceDefinitionIdForSimulationAction(input, action);
  if (!definitionId) return false;
  const roles = rolesForCardId(definitionId);
  if (definitionId === "onr_v1_165_junkyard-bbs") return true;
  if (roles.some((role) => role === "memory" || role === "memory_support"))
    return false;
  if (roles.some((role) => isRunnerPressureRole(role))) return false;
  if (roles.some((role) => isRunnerNonAdditiveUtilityRole(role))) return true;
  if (roles.some((role) => role.startsWith("breaker_"))) return true;
  return roles.some(
    (role) =>
      role === "resource" ||
      role === "setup" ||
      role === "draw" ||
      role === "tag_risk" ||
      isRunnerEconomyRole(role),
  );
}

function sourceDefinitionIdForSimulationAction(
  input: AiDecisionInput,
  action: LegalAction,
): string | undefined {
  if (action.source === "basic_action" || action.source === "game_rule")
    return undefined;
  return findVisibleCard(input, action.source)?.definitionId;
}

function isRunnerEconomyRole(role: string): boolean {
  return role === "economy" || role === "tempo" || role.includes("economy");
}

function isRunnerPressureRole(role: string): boolean {
  return (
    role === "run_pressure" ||
    role === "access" ||
    role.includes("pressure") ||
    role.includes("interface") ||
    role.includes("multiaccess")
  );
}

function isRunnerNonAdditiveUtilityRole(role: string): boolean {
  return (
    role === "program_search" ||
    role === "stack_search" ||
    role === "trash_recovery" ||
    role === "search_trash" ||
    role.includes("setup.recovery") ||
    role.includes("setup.stack_filter")
  );
}

function serverIdForCorpInstalledCard(
  state: GameState,
  cardId: string,
): string | undefined {
  const installedCardId = cardId as CardInstanceId;
  for (const server of state.corp.servers) {
    if (
      server.ice.includes(installedCardId) ||
      server.root.includes(installedCardId)
    )
      return server.id;
  }
  return undefined;
}

function cardTargetTypeForInstance(
  state: GameState,
  cardId: string,
): ProgressionCardTargetType {
  const definitionId = state.cardInstances[cardId]?.definitionId;
  if (!definitionId) return "unknown";
  const type =
    DEMO_CARDS_BY_ID[definitionId]?.type ?? RUNTIME_CARDS[definitionId]?.type;
  return progressionCardTargetType(type);
}

function progressionCardTargetType(
  type: string | undefined,
): ProgressionCardTargetType {
  if (
    type === "agenda" ||
    type === "asset" ||
    type === "upgrade" ||
    type === "ice"
  )
    return type;
  return "unknown";
}

function sortedUniqueProgressionCardTargetTypes(
  values: ProgressionCardTargetType[],
): ProgressionCardTargetType[] {
  return [...new Set(values)].sort();
}

function advancedAgendaStealSourceForAction(
  stateBeforeAction: GameState,
  action: LegalAction,
  targetCardIds: CardInstanceId[],
): "remote" | "central" | "unknown" | undefined {
  if (action.type !== "steal_agenda") return undefined;
  const stolenSources = targetCardIds
    .map((cardId) => {
      const instance = stateBeforeAction.cardInstances[cardId];
      if (!instance || instance.advancementCounters <= 0) return undefined;
      if (cardTargetTypeForInstance(stateBeforeAction, cardId) !== "agenda")
        return undefined;
      if (
        instance.zone.side !== "corp" ||
        !["serverRoot", "rd", "hq", "archives"].includes(instance.zone.zone)
      )
        return undefined;
      if (
        instance.zone.zone === "serverRoot" &&
        instance.zone.serverId.startsWith("remote_")
      )
        return "remote" as const;
      if (
        instance.zone.zone === "rd" ||
        instance.zone.zone === "hq" ||
        instance.zone.zone === "archives"
      )
        return "central" as const;
      return "unknown" as const;
    })
    .filter((source): source is "remote" | "central" | "unknown" =>
      Boolean(source),
    );
  return stolenSources.includes("remote")
    ? "remote"
    : stolenSources.includes("central")
      ? "central"
      : stolenSources[0];
}

function finalAdvanceAssessmentForSimulationAction(
  stateBeforeAction: GameState,
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
  targetCardIds: CardInstanceId[],
  advancementCountersAdded: number,
): {
  finalAdvance: boolean;
  unsafeFinalAdvance?: boolean;
  protectedFinalAdvance?: boolean;
  remoteProtectionScore?: number;
  runnerContestRisk?: "low" | "medium" | "high" | "unknown";
  advancesRemainingAfterAction?: number;
} {
  if (action.side !== "corp" || advancementCountersAdded <= 0)
    return { finalAdvance: false };
  const cardId = targetCardIds.find(
    (candidate) =>
      cardTargetTypeForInstance(stateBeforeAction, candidate) === "agenda",
  );
  if (!cardId || !targetServerId?.startsWith("remote_"))
    return { finalAdvance: false };
  const instance = stateBeforeAction.cardInstances[cardId];
  if (!instance) return { finalAdvance: false };
  const definitionId = instance.definitionId;
  const requirement =
    DEMO_CARDS_BY_ID[definitionId]?.advancementRequirement ??
    RUNTIME_CARDS[definitionId]?.numeric.advancementRequirement ??
    0;
  const countersAfter = instance.advancementCounters + advancementCountersAdded;
  const advancesRemainingAfterAction = Math.max(0, requirement - countersAfter);
  if (advancesRemainingAfterAction > 1) return { finalAdvance: false };
  const remoteProtectionScore = remoteProtectionScoreForSimulation(
    stateBeforeAction,
    input,
    targetServerId,
    simulationActionCreditCost(action),
  );
  const runnerContestRisk = runnerContestRiskForSimulation(
    stateBeforeAction,
    input,
    targetServerId,
  );
  const sameTurnScoreLikely = advancesRemainingAfterAction === 0;
  const unsafeFinalAdvance =
    !sameTurnScoreLikely &&
    (runnerContestRisk === "high" || remoteProtectionScore < 60);
  return {
    finalAdvance: true,
    unsafeFinalAdvance,
    protectedFinalAdvance: !unsafeFinalAdvance,
    remoteProtectionScore,
    runnerContestRisk,
    advancesRemainingAfterAction,
  };
}

function isProtectBeforeAdvanceSimulationAction(
  stateBeforeAction: GameState,
  input: AiDecisionInput,
  action: LegalAction,
  targetServerId: string | undefined,
): boolean {
  if (action.side !== "corp" || !targetServerId?.startsWith("remote_"))
    return false;
  if (!remoteHasNearFinalAgenda(stateBeforeAction, targetServerId))
    return false;
  if (action.type === "install_card" && action.payload?.placement === "ice")
    return true;
  if (
    action.type === "install_card" &&
    action.payload?.placement !== "ice" &&
    isProtectionDefinitionId(
      stateBeforeAction.cardInstances[action.source]?.definitionId,
    )
  )
    return true;
  if (action.type === "gain_credit") {
    const protectionBefore = remoteProtectionScoreForSimulation(
      stateBeforeAction,
      input,
      targetServerId,
      0,
    );
    const protectionAfter = remoteProtectionScoreForSimulation(
      stateBeforeAction,
      input,
      targetServerId,
      -1,
    );
    return protectionBefore < 60 && protectionAfter > protectionBefore;
  }
  return false;
}

function remoteHasNearFinalAgenda(state: GameState, serverId: string): boolean {
  const server = state.corp.servers.find(
    (candidate) => candidate.id === serverId,
  );
  if (!server) return false;
  return server.root.some((cardId) => {
    const instance = state.cardInstances[cardId];
    if (!instance) return false;
    if (cardTargetTypeForInstance(state, cardId) !== "agenda") return false;
    const requirement =
      DEMO_CARDS_BY_ID[instance.definitionId]?.advancementRequirement ??
      RUNTIME_CARDS[instance.definitionId]?.numeric.advancementRequirement ??
      0;
    return Math.max(0, requirement - instance.advancementCounters) <= 2;
  });
}

function remoteProtectionScoreForSimulation(
  state: GameState,
  input: AiDecisionInput,
  serverId: string,
  actionCreditCostValue: number,
): number {
  const server = state.corp.servers.find(
    (candidate) => candidate.id === serverId,
  );
  if (!server) return 0;
  const visibleServer = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  const rezzedIce = server.ice.filter(
    (cardId) => state.cardInstances[cardId]?.rezzed === true,
  ).length;
  const unrezzedIce = server.ice.length - rezzedIce;
  const cheapestRez = Math.min(
    ...server.ice
      .filter((cardId) => state.cardInstances[cardId]?.rezzed !== true)
      .map((cardId) =>
        rezCostForDefinitionId(state.cardInstances[cardId]?.definitionId),
      )
      .filter((cost) => cost > 0),
  );
  const hasAffordableUnrezzed =
    Number.isFinite(cheapestRez) &&
    state.corp.credits - actionCreditCostValue >= cheapestRez;
  const rootProtection = server.root.filter((cardId) =>
    isProtectionDefinitionId(state.cardInstances[cardId]?.definitionId),
  ).length;
  const risk = runnerContestRiskForSimulation(state, input, serverId);
  return (
    Math.min(server.ice.length, 3) * 22 +
    rezzedIce * 32 +
    (unrezzedIce > 0 && hasAffordableUnrezzed ? 28 : 0) +
    rootProtection * 35 +
    (visibleServer?.ice.some((ice) => ice.rezzed === true) ? 8 : 0) +
    (risk === "low" ? 35 : risk === "medium" ? 5 : -45)
  );
}

function runnerContestRiskForSimulation(
  state: GameState,
  input: AiDecisionInput,
  serverId: string,
): "low" | "medium" | "high" | "unknown" {
  const server = input.playerView.servers.find(
    (candidate) => candidate.id === serverId,
  );
  if (!server) return "unknown";
  if (server.ice.length <= 0) return "high";
  const runnerCredits = input.playerView.opponent.credits;
  const breakers =
    input.playerView.opponent.rig?.filter((card) =>
      card.definitionId
        ? RUNTIME_CARDS[card.definitionId]?.subtypes.includes("icebreaker")
        : false,
    ).length ?? 0;
  const rezzedIce =
    state.corp.servers
      .find((candidate) => candidate.id === serverId)
      ?.ice.filter((cardId) => state.cardInstances[cardId]?.rezzed === true)
      .length ?? 0;
  if (runnerCredits >= 6 && breakers > 0) return "high";
  if (rezzedIce > 0 || runnerCredits <= 3 || breakers === 0) return "low";
  return "medium";
}

function isProtectionDefinitionId(definitionId: string | undefined): boolean {
  if (!definitionId) return false;
  const normalized = definitionId.toLocaleLowerCase("en-US");
  return (
    normalized.includes("red-herrings") ||
    normalized.includes("tesseract") ||
    normalized.includes("namatoki")
  );
}

function rezCostForDefinitionId(definitionId: string | undefined): number {
  if (!definitionId) return 0;
  return (
    DEMO_CARDS_BY_ID[definitionId]?.rezCost ??
    RUNTIME_CARDS[definitionId]?.numeric.rezCost ??
    0
  );
}

function simulationActionCreditCost(action: LegalAction): number {
  return action.costs.reduce(
    (sum, cost) => sum + Math.max(0, cost.credits ?? 0),
    0,
  );
}

function advancementCountersAddedForSimulationAction(
  action: LegalAction,
  event: PublicGameEvent,
): number {
  const candidates = [
    action.payload?.addedAdvancementCounters,
    action.payload?.advancementCountersAdded,
    event.publicPayload.addedAdvancementCounters,
    event.publicPayload.advancementCountersAdded,
  ];
  for (const value of candidates) {
    if (typeof value === "number" && Number.isFinite(value) && value > 0)
      return value;
  }
  return action.type === "advance_card" ? 1 : 0;
}

function metricsFor(
  actionSequence: AiSimulationSummary["actionSequence"],
  errors: string[],
  replayOk: boolean,
  holdout: boolean,
): AiQualityMetrics {
  const actions = actionSequence.length || 1;
  const reasonCodeCoverage = sortedUnique(
    actionSequence.map((entry) =>
      entry.reasonCode.split(".").slice(0, 2).join("."),
    ),
  );
  const doctrine = summarizeDoctrineQualityMetrics(actionSequence);
  return {
    illegalActions: errors.length,
    fallbackRate: round(
      actionSequence.filter((entry) => entry.fallbackUsed).length / actions,
    ),
    timeoutRate: round(
      actionSequence.filter((entry) => entry.timeoutUsed).length / actions,
    ),
    reasonCodeCoverage,
    actionTypeCoverage: sortedUnique(
      actionSequence.map((entry) => entry.actionType),
    ),
    roleCoverage: sortedUnique(
      actionSequence.flatMap((entry) =>
        entry.evidence
          .filter((item) => item.startsWith("role:"))
          .map((item) => item.slice("role:".length)),
      ),
    ),
    progressScore: round(
      actionSequence.length + (replayOk ? 10 : 0) - errors.length * 10,
    ),
    holdout,
    doctrine,
  };
}

function qualityTagsForAction(
  input: AiDecisionInput,
  action: LegalAction,
  decision: AiDecision,
): string[] {
  const tags: string[] = [];
  const features = extractAiFeatures(input);
  const sourceCard =
    action.source === "basic_action" || action.source === "game_rule"
      ? undefined
      : findVisibleCard(input, action.source);
  const sourceDefinition = sourceCard?.definitionId
    ? DEMO_CARDS_BY_ID[sourceCard.definitionId]
    : undefined;
  const targetServerId =
    typeof action.payload?.serverId === "string"
      ? action.payload.serverId
      : undefined;
  const targetServer = targetServerId
    ? features.serverFeaturesById.get(targetServerId)
    : undefined;
  const agendaInHand = input.playerView.own.gripOrHq.filter(
    (card) =>
      card.definitionId &&
      DEMO_CARDS_BY_ID[card.definitionId]?.type === "agenda",
  ).length;
  const legalScoreAvailable =
    input.side === "corp" &&
    input.legalActions.some((candidate) => candidate.type === "score_agenda");
  const legalTrashAvailable =
    input.side === "runner" &&
    input.legalActions.some(
      (candidate) => candidate.type === "trash_accessed_card",
    );
  const lowCredits = input.playerView.own.credits <= 1;
  const economyAction =
    action.type === "gain_credit" ||
    ((action.type === "play_event" || action.type === "play_operation") &&
      rolesForAction(input, action).some(
        (role) => role.includes("economy") || role === "tempo",
      ));
  const economyStallExempt = isEconomyStallExemptAction(
    input,
    action,
    decision,
  );
  const visibleRemoteContest =
    targetServerId?.startsWith("remote_") === true &&
    (targetServer?.rootCount ?? 0) > 0;

  if (
    input.side === "corp" &&
    action.type === "install_card" &&
    action.payload?.placement !== "ice" &&
    sourceDefinition?.type === "agenda"
  ) {
    if (
      targetServerId === "new_remote" ||
      ((targetServer?.iceCount ?? 0) === 0 &&
        (targetServer?.rootCount ?? 0) === 0)
    )
      tags.push("naked_agenda_install");
  }
  if (
    input.side === "corp" &&
    agendaInHand >= 3 &&
    !isAgendaFloodExposureExemptAction(action, decision, sourceDefinition)
  )
    tags.push("agenda_flood_exposure");
  if (legalScoreAvailable && action.type !== "score_agenda")
    tags.push("score_window_missed");
  if (
    input.side === "corp" &&
    action.type === "install_card" &&
    targetServerId?.startsWith("remote_") &&
    ((action.payload?.placement === "ice" &&
      (targetServer?.iceCount ?? 0) >= 2) ||
      (action.payload?.placement !== "ice" &&
        (targetServer?.rootCount ?? 0) >= 2))
  ) {
    tags.push("remote_overbuild");
  }
  if (lowCredits && !economyAction && !economyStallExempt)
    tags.push("economy_stall");
  if (
    input.side === "runner" &&
    features.rigRoles.size === 0 &&
    action.type === "start_run" &&
    !visibleRemoteContest &&
    input.playerView.opponent.agendaPoints <
      input.playerView.agendaPointsToWin - 2
  )
    tags.push("rig_stall");
  if (legalTrashAvailable && action.type !== "trash_accessed_card")
    tags.push("asset_trash_neglect");
  if (decision.timeoutUsed) tags.push("timeout");
  if (decision.fallbackUsed) tags.push("fallback");
  return sortedUnique(tags);
}

function isEconomyStallExemptAction(
  input: AiDecisionInput,
  action: LegalAction,
  decision: AiDecision,
): boolean {
  if (decision.fallbackUsed) return true;
  if (decision.reasonCode.endsWith(".recover_economy")) return true;
  if (
    action.type === "mandatory_draw" ||
    action.type === "end_turn" ||
    action.type === "decline_rez" ||
    action.type === "resolve_choice"
  )
    return true;
  if (input.side !== "runner") return false;
  return (
    action.type === "pump_breaker" ||
    action.type === "break_subroutine" ||
    action.type === "continue_run" ||
    action.type === "access_card" ||
    action.type === "steal_agenda"
  );
}

function isAgendaFloodExposureExemptAction(
  action: LegalAction,
  decision: AiDecision,
  sourceDefinition?: { type?: string },
): boolean {
  if (decision.fallbackUsed) return true;
  if (decision.reasonCode.endsWith(".recover_economy")) return true;
  if (
    decision.reasonCode.endsWith(".protect_hq") ||
    decision.reasonCode.endsWith(".protect_rnd")
  )
    return true;
  if (
    action.type === "install_card" &&
    action.payload?.placement !== "ice" &&
    sourceDefinition?.type !== "agenda"
  )
    return true;
  return (
    action.type === "mandatory_draw" ||
    action.type === "end_turn" ||
    action.type === "decline_rez" ||
    action.type === "rez_ice" ||
    action.type === "resolve_choice"
  );
}

function repeatedLowValueCentralRunTags(
  actionSequence: AiSimulationSummary["actionSequence"],
): string[] {
  const tags: string[] = [];
  const lastCentralRunByServer = new Map<string, number>();
  for (const [index, entry] of actionSequence.entries()) {
    if (
      entry.side !== "runner" ||
      entry.actionType !== "start_run" ||
      !entry.targetServerId ||
      !["rd", "hq", "archives"].includes(entry.targetServerId)
    )
      continue;
    const previous = lastCentralRunByServer.get(entry.targetServerId);
    if (
      previous !== undefined &&
      index - previous <= 4 &&
      !entry.reasonCode.includes("contest") &&
      !entry.reasonCode.includes("trash")
    )
      tags.push("repeated_low_value_central_run");
    lastCentralRunByServer.set(entry.targetServerId, index);
  }
  return tags;
}

function doctrineMetricsFor(tags: string[]): AiDoctrineQualityMetrics {
  return {
    nakedAgendaInstalls: countTag(tags, "naked_agenda_install"),
    agendaFloodExposure: countTag(tags, "agenda_flood_exposure"),
    scoreWindowMissed: countTag(tags, "score_window_missed"),
    remoteOverbuild: countTag(tags, "remote_overbuild"),
    economyStall: countTag(tags, "economy_stall"),
    repeatedLowValueCentralRun: countTag(
      tags,
      "repeated_low_value_central_run",
    ),
    rigStall: countTag(tags, "rig_stall"),
    assetTrashNeglect: countTag(tags, "asset_trash_neglect"),
  };
}

function emptyDoctrineCaseExamples(): Record<
  AiDoctrineQualityMetricName,
  AiDoctrineQualityCaseExample[]
> {
  return DOCTRINE_QUALITY_METRIC_NAMES.reduce(
    (examples, metric) => ({
      ...examples,
      [metric]: [],
    }),
    {} as Record<AiDoctrineQualityMetricName, AiDoctrineQualityCaseExample[]>,
  );
}

function doctrineMetricForQualityTag(
  tag: string,
): AiDoctrineQualityMetricName | undefined {
  switch (tag) {
    case "naked_agenda_install":
      return "nakedAgendaInstalls";
    case "agenda_flood_exposure":
      return "agendaFloodExposure";
    case "score_window_missed":
      return "scoreWindowMissed";
    case "remote_overbuild":
      return "remoteOverbuild";
    case "economy_stall":
      return "economyStall";
    case "rig_stall":
      return "rigStall";
    case "asset_trash_neglect":
      return "assetTrashNeglect";
    default:
      return undefined;
  }
}

function collectRepeatedLowValueCentralRunExamples(
  summary: AiSimulationSummary,
  examples: Record<AiDoctrineQualityMetricName, AiDoctrineQualityCaseExample[]>,
  maxExamplesPerMetric: number,
): void {
  const metric: AiDoctrineQualityMetricName = "repeatedLowValueCentralRun";
  const lastCentralRunByServer = new Map<string, number>();
  for (const [actionIndex, entry] of summary.actionSequence.entries()) {
    if (
      entry.side !== "runner" ||
      entry.actionType !== "start_run" ||
      !entry.targetServerId ||
      !["rd", "hq", "archives"].includes(entry.targetServerId)
    )
      continue;
    const previous = lastCentralRunByServer.get(entry.targetServerId);
    if (
      previous !== undefined &&
      actionIndex - previous <= 4 &&
      !entry.reasonCode.includes("contest") &&
      !entry.reasonCode.includes("trash") &&
      examples[metric].length < maxExamplesPerMetric
    ) {
      examples[metric].push(
        doctrineCaseExample(summary.seed, actionIndex, entry, metric),
      );
    }
    lastCentralRunByServer.set(entry.targetServerId, actionIndex);
  }
}

function doctrineCaseExample(
  seed: string,
  actionIndex: number,
  entry: AiSimulationSummary["actionSequence"][number],
  metric: AiDoctrineQualityMetricName,
): AiDoctrineQualityCaseExample {
  return {
    metric,
    seed,
    actionIndex,
    stateVersionBefore: entry.stateVersionBefore,
    side: entry.side,
    actionType: entry.actionType,
    reasonCode: entry.reasonCode,
    ...(entry.targetServerId ? { targetServerId: entry.targetServerId } : {}),
    qualityTags: entry.qualityTags.slice().sort(),
  };
}

function isRedactionSafeCaseAnalysis(
  analysis: AiDoctrineQualityCaseAnalysis,
): boolean {
  const serialized = JSON.stringify(analysis);
  return !FORBIDDEN_AI_INPUT_FIELDS.some((needle) =>
    serialized.includes(needle),
  );
}

function countTag(tags: string[], tag: string): number {
  return tags.filter((candidate) => candidate === tag).length;
}

function isHoldoutSeed(seed: string): boolean {
  return SOAK_SEEDS.holdoutSeeds.includes(seed);
}

function sortedUnique(values: string[]): string[] {
  return [...new Set(values)].sort();
}

function fnv1a(value: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function round(value: number): number {
  return Math.round(value * 1000) / 1000;
}

function minDefined(values: number[]): number {
  return values.length > 0 ? Math.min(...values) : 0;
}

function roundScore(value: number): number {
  return Math.round(value * 100) / 100;
}

function confidence(score: number): number {
  return Math.max(0.1, Math.min(0.99, round(score / 1000)));
}

function compareAction(left: LegalAction, right: LegalAction): number {
  return left.actionId.localeCompare(right.actionId);
}
